// ExecutableCanonicalVectorV1 is a generated byte vector, not a metadata
// recipe. FalsePredicateIDs is populated for predicate-negative vectors.
type ExecutableCanonicalVectorV1 struct {
	VectorID          string
	Bytes             []byte
	RequiredError     CanonicalRequiredError
	FalsePredicateIDs []string
}

type ExecutableCanonicalVectorSetV1 struct {
	SchemaID   string
	Positive   []byte
	Rejections []ExecutableCanonicalVectorV1
}

type canonicalPredicateContextV1 struct {
	recordPositiveByType  map[string][]byte
	recordByTypeAndDigest map[string]map[string][]byte
	validDigestByTarget   map[string]map[string]struct{}
	exactBytes            []byte
}

// GenerateCanonicalCatalogPositiveVectorsV1 materializes the complete frozen
// positive corpus. Record-valued fields and arrays are resolved recursively,
// so the result never substitutes an empty object for a required record.
func GenerateCanonicalCatalogPositiveVectorsV1(catalog CanonicalVectorCatalogV1) (map[string][]byte, error) {
	positives, _, err := generateCanonicalCatalogPositiveVectorsV1(catalog)
	return positives, err
}

func generateCanonicalCatalogPositiveVectorsV1(catalog CanonicalVectorCatalogV1) (map[string][]byte, *canonicalPredicateContextV1, error) {
	if err := catalog.Validate(); err != nil {
		return nil, nil, err
	}
	byRecord := make(map[string]CanonicalVectorEntryV1, len(catalog.Entries))
	for _, entry := range catalog.Entries {
		if prior, duplicate := byRecord[entry.RecordName]; duplicate && prior.SchemaID != entry.SchemaID {
			return nil, nil, fmt.Errorf("record target %s is ambiguous", entry.RecordName)
		}
		byRecord[entry.RecordName] = entry
	}
	prototypes := make(map[string][]byte, len(catalog.Entries))
	visiting := make(map[string]bool)
	var generate func(CanonicalVectorEntryV1) ([]byte, error)
	generate = func(entry CanonicalVectorEntryV1) ([]byte, error) {
		if positive, ok := prototypes[entry.SchemaID]; ok {
			return append([]byte(nil), positive...), nil
		}
		if visiting[entry.SchemaID] {
			return nil, fmt.Errorf("required record target cycle at %s", entry.SchemaID)
		}
		visiting[entry.SchemaID] = true
		defer delete(visiting, entry.SchemaID)
		positive, err := GenerateMinimalCanonicalVectorV1(entry)
		if err != nil {
			return nil, err
		}
		if entry.RecordName == "ArtifactBlobV1" && entry.SchemaID == "artifact-blob-v1" {
			prototypes[entry.SchemaID] = append([]byte(nil), positive...)
			return positive, nil
		}
		values, _, _, err := decodeCanonicalVectorObjectV1(positive)
		if err != nil {
			return nil, err
		}
		for _, field := range entry.Fields {
			raw, present := values[field.FieldPath]
			if !present {
				continue
			}
			switch field.JSONType {
			case WireObject:
				target, ok := byRecord[field.RecordTarget]
				if !ok {
					// Retained predecessor records are validated by their frozen V1
					// constructors and are not duplicated in the V4 catalog.
					continue
				}
				values[field.FieldPath], err = generate(target)
			case WireArray:
				targetName := field.RecordTarget
				if targetName == "" {
					elementType := arrayElementTypeV1(field.ValueType)
					if target, ok := byRecord[elementType]; ok {
						targetName = target.RecordName
					}
				}
				if targetName == "" {
					continue
				}
				target, ok := byRecord[targetName]
				if !ok {
					continue
				}
				var elements []json.RawMessage
				if json.Unmarshal(raw, &elements) != nil {
					return nil, fmt.Errorf("%s.%s positive is not an array", entry.SchemaID, field.FieldPath)
				}
				for index := range elements {
					elements[index], err = generate(target)
					if err != nil {
						break
					}
				}
				if err == nil {
					values[field.FieldPath], err = json.Marshal(elements)
				}
			}
			if err != nil {
				return nil, err
			}
		}
		if err := applyPositivePredicatesV1(entry, values); err != nil {
			return nil, err
		}
		if err := applyEd25519VectorsV1(entry, values); err != nil {
			return nil, err
		}
		for index, field := range entry.Fields {
			if !isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
				continue
			}
			preimage, err := marshalCanonicalVectorObjectV1(entry.Fields, values, field.FieldPath)
			if err != nil {
				return nil, err
			}
			values[field.FieldPath], _ = json.Marshal(sha256Hex(preimage))
		}
		positive, err = marshalCanonicalVectorObjectV1(entry.Fields, values, "")
		if err != nil {
			return nil, err
		}
		prototypes[entry.SchemaID] = append([]byte(nil), positive...)
		return positive, nil
	}
	for _, entry := range catalog.Entries {
		if _, err := generate(entry); err != nil {
			return nil, nil, err
		}
	}
	context := newEmptyCanonicalPredicateContextV1()
	if err := context.addFrozenRetainedRecords(); err != nil {
		return nil, nil, err
	}
	if artifact, ok := byRecord["ArtifactBlobV1"]; ok {
		context.exactBytes = append([]byte(nil), prototypes[artifact.SchemaID]...)
	}
	result := make(map[string][]byte, len(catalog.Entries))
	visiting = make(map[string]bool)
	prototypeBackedTypes := make(map[string]bool)
	var finalizationStack []string
	var finalize func(CanonicalVectorEntryV1) ([]byte, error)
	finalize = func(entry CanonicalVectorEntryV1) ([]byte, error) {
		if positive, ok := result[entry.SchemaID]; ok {
			return append([]byte(nil), positive...), nil
		}
		if visiting[entry.SchemaID] {
			return nil, fmt.Errorf("required record target cycle at %s: %s", entry.SchemaID, strings.Join(append(finalizationStack, entry.SchemaID), " -> "))
		}
		visiting[entry.SchemaID] = true
		finalizationStack = append(finalizationStack, entry.SchemaID)
		defer func() {
			delete(visiting, entry.SchemaID)
			finalizationStack = finalizationStack[:len(finalizationStack)-1]
		}()
		if entry.RecordName == "ArtifactBlobV1" && entry.SchemaID == "artifact-blob-v1" {
			result[entry.SchemaID] = append([]byte(nil), prototypes[entry.SchemaID]...)
			context.addRecord(entry.RecordName, prototypes[entry.SchemaID])
			return append([]byte(nil), prototypes[entry.SchemaID]...), nil
		}
		values, _, _, err := decodeCanonicalVectorObjectV1(prototypes[entry.SchemaID])
		if err != nil {
			return nil, err
		}
		for _, field := range entry.Fields {
			raw, present := values[field.FieldPath]
			if !present {
				continue
			}
			targetName := field.RecordTarget
			if targetName == "" && field.JSONType == WireArray {
				targetName = arrayElementTypeV1(field.ValueType)
			}
			target, hasTarget := byRecord[targetName]
			switch {
			case hasTarget && field.JSONType == WireObject:
				values[field.FieldPath], err = finalize(target)
			case hasTarget && field.JSONType == WireArray:
				var elements []json.RawMessage
				if json.Unmarshal(raw, &elements) != nil {
					return nil, fmt.Errorf("%s.%s positive is not an array", entry.SchemaID, field.FieldPath)
				}
				for index := range elements {
					elements[index], err = finalize(target)
					if err != nil {
						break
					}
				}
				if err == nil {
					values[field.FieldPath], err = json.Marshal(elements)
				}
			}
			if err != nil {
				return nil, err
			}
		}
		for index, field := range entry.Fields {
			if field.DigestTarget == "" || isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
				continue
			}
			if _, present := values[field.FieldPath]; !present {
				continue
			}
			for _, member := range selectedDigestTargetMembersV1(field.DigestTarget, values) {
				if member == "exact-bytes" {
					if len(context.exactBytes) == 0 {
						return nil, fmt.Errorf("%s.%s cannot resolve exact emitted bytes", entry.SchemaID, field.FieldPath)
					}
					continue
				}
				target, ok := byRecord[member]
				if !ok {
					if len(context.recordPositiveByType[member]) != 0 {
						continue
					}
					return nil, fmt.Errorf("%s.%s cannot resolve emitted target type %s", entry.SchemaID, field.FieldPath, member)
				}
				if visiting[target.SchemaID] {
					context.addRecordVariant(member, prototypes[target.SchemaID])
					prototypeBackedTypes[member] = true
					continue
				}
				if _, err := finalize(target); err != nil {
					return nil, err
				}
			}
		}
		for _, predicate := range entry.Predicates {
			if predicate.PredicateID != "P-PARENT-001" {
				continue
			}
			target, ok := byRecord["PhaseCheckpointV2"]
			if !ok {
				return nil, errors.New("P-PARENT-001 source PhaseCheckpointV2 is unavailable")
			}
			if visiting[target.SchemaID] {
				context.addRecordVariant(target.RecordName, prototypes[target.SchemaID])
				prototypeBackedTypes[target.RecordName] = true
				continue
			}
			if _, err := finalize(target); err != nil {
				return nil, err
			}
		}
		if err := applyTypedReferencePositivesV1(entry, values, context); err != nil {
			return nil, err
		}
		if err := applyPositivePredicatesV1(entry, values, context); err != nil {
			return nil, err
		}
		if err := applyEd25519VectorsV1(entry, values); err != nil {
			return nil, err
		}
		for index, field := range entry.Fields {
			if !isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
				continue
			}
			preimage, err := marshalCanonicalVectorObjectV1(entry.Fields, values, field.FieldPath)
			if err != nil {
				return nil, err
			}
			values[field.FieldPath], _ = json.Marshal(sha256Hex(preimage))
		}
		positive, err := marshalCanonicalVectorObjectV1(entry.Fields, values, "")
		if err != nil {
			return nil, err
		}
		result[entry.SchemaID] = append([]byte(nil), positive...)
		context.addRecord(entry.RecordName, positive)
		return positive, nil
	}
	for _, entry := range catalog.Entries {
		if _, err := finalize(entry); err != nil {
			return nil, nil, err
		}
	}
	context, err := newCanonicalPredicateContextV1(catalog, result)
	if err != nil {
		return nil, nil, err
	}
	for recordType := range prototypeBackedTypes {
		for _, entry := range catalog.Entries {
			if entry.RecordName == recordType {
				context.addRecordVariant(recordType, prototypes[entry.SchemaID])
			}
		}
	}
	if err := assertFinalTypedReferenceContextV1(catalog, prototypes, result, context, prototypeBackedTypes); err != nil {
		return nil, nil, err
	}
	for _, entry := range catalog.Entries {
		if err := validateCanonicalCatalogPositiveV1(entry, result[entry.SchemaID], byRecord, make(map[string]bool), context); err != nil {
			return nil, nil, fmt.Errorf("validate %s positive: %w", entry.SchemaID, err)
		}
	}
	return result, context, nil
}

func newEmptyCanonicalPredicateContextV1() *canonicalPredicateContextV1 {
	return &canonicalPredicateContextV1{
		recordPositiveByType:  make(map[string][]byte),
		recordByTypeAndDigest: make(map[string]map[string][]byte),
		validDigestByTarget:   make(map[string]map[string]struct{}),
	}
}

func newCanonicalPredicateContextV1(catalog CanonicalVectorCatalogV1, positives map[string][]byte) (*canonicalPredicateContextV1, error) {
	context := newEmptyCanonicalPredicateContextV1()
	if err := context.addFrozenRetainedRecords(); err != nil {
		return nil, err
	}
	for _, entry := range catalog.Entries {
		positive := positives[entry.SchemaID]
		if len(positive) == 0 {
			return nil, fmt.Errorf("catalog type %s has no positive record", entry.RecordName)
		}
		context.addRecord(entry.RecordName, positive)
		if entry.RecordName == "ArtifactBlobV1" {
			context.exactBytes = append([]byte(nil), positive...)
		}
	}
	for _, entry := range catalog.Entries {
		for index, field := range entry.Fields {
			if field.DigestTarget == "" || isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
				continue
			}
			members := digestTargetMembersV1(field.DigestTarget)
			if len(members) == 0 {
				return nil, fmt.Errorf("%s.%s has unresolved digest target %q", entry.SchemaID, field.FieldPath, field.DigestTarget)
			}
			for _, member := range members {
				if member == "exact-bytes" {
					if len(context.exactBytes) == 0 {
						return nil, fmt.Errorf("%s.%s has no exact emitted byte target", entry.SchemaID, field.FieldPath)
					}
					context.addValidDigest(field.DigestTarget, sha256Hex(context.exactBytes))
					continue
				}
				positive := context.recordPositiveByType[member]
				if len(positive) == 0 {
					return nil, fmt.Errorf("%s.%s has unavailable target type %s", entry.SchemaID, field.FieldPath, member)
				}
				context.addValidDigest(field.DigestTarget, sha256Hex(positive))
			}
		}
	}
	return context, nil
}

var frozenRetainedCanonicalRecordsV1 = map[string]string{
	"AuthorizationSealV1":        `{"schema":"authorization-seal-v1"}`,
	"ContextCapsuleV3":           `{"policy_version":"context-capsule-v3"}`,
	"ExecutionBoundsV1":          `{"max_iterations":1,"session_timeout":"1s","idle_timeout":"1s","wall_clock_timeout":"1s","aggregate_wall_clock_timeout":"1s","finalize":false,"max_incomplete_tasks":0,"max_initial_active_findings":0,"max_ralphex_invocations":1,"max_review_reports":1,"max_mutation_leases":1,"max_total_fix_batches":1,"max_changed_files":1,"max_changed_bytes":1}`,
	"ExpectedMergeContentV1":     `{"derivation_policy":"phase3-ready-tree-v1"}`,
	"GitHubLifecycleLimitsV1":    `{"schema":"github-lifecycle-limits-v1"}`,
	"GovernanceActivationV1":     `{"kind":"GovernanceActivationV1","policy_version":"context-capsule-v3"}`,
	"MergePolicyV1":              `{"schema":"merge-policy-v1"}`,
	"PhaseCheckpointV1":          `{"kind":"DESIGN_ACCEPTED"}`,
	"ReadyAuthorityBindingV1":    `{"schema":"ready-authority-binding-v1"}`,
	"SealedMergeAuthorizationV1": `{"schema":"sealed-merge-authorization-v1"}`,
	"TargetRefCommitmentV1":      `{"schema":"target-ref-commitment-v1"}`,
}

func (context *canonicalPredicateContextV1) addFrozenRetainedRecords() error {
	for recordType, encoded := range frozenRetainedCanonicalRecordsV1 {
		if !json.Valid([]byte(encoded)) {
			return fmt.Errorf("retained canonical record %s is invalid", recordType)
		}
		context.addRecord(recordType, []byte(encoded))
	}
	return nil
}

func (context *canonicalPredicateContextV1) addRecord(recordType string, record []byte) {
	copyOfRecord := append([]byte(nil), record...)
	context.recordPositiveByType[recordType] = copyOfRecord
	digest := sha256Hex(record)
	if context.recordByTypeAndDigest[recordType] == nil {
		context.recordByTypeAndDigest[recordType] = make(map[string][]byte)
	}
	context.recordByTypeAndDigest[recordType][digest] = copyOfRecord
	context.addValidDigest(recordType, digest)
}

func (context *canonicalPredicateContextV1) addRecordVariant(recordType string, record []byte) {
	copyOfRecord := append([]byte(nil), record...)
	if len(context.recordPositiveByType[recordType]) == 0 {
		context.recordPositiveByType[recordType] = copyOfRecord
	}
	digest := sha256Hex(record)
	if context.recordByTypeAndDigest[recordType] == nil {
		context.recordByTypeAndDigest[recordType] = make(map[string][]byte)
	}
	context.recordByTypeAndDigest[recordType][digest] = copyOfRecord
	context.addValidDigest(recordType, digest)
}

func (context *canonicalPredicateContextV1) recordForDigest(recordType, digest string) ([]byte, bool) {
	if context == nil || context.recordByTypeAndDigest[recordType] == nil {
		return nil, false
	}
	record, ok := context.recordByTypeAndDigest[recordType][digest]
	return append([]byte(nil), record...), ok
}

func (context *canonicalPredicateContextV1) addValidDigest(target, digest string) {
	if context.validDigestByTarget[target] == nil {
		context.validDigestByTarget[target] = make(map[string]struct{})
	}
	context.validDigestByTarget[target][digest] = struct{}{}
}

func digestTargetMembersV1(target string) []string {
	if index := strings.IndexByte(target, '['); index >= 0 {
		target = target[:index]
	}
	parts := strings.Split(target, "-or-")
	result := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" && !containsCanonicalVectorStringV1(result, part) {
			result = append(result, part)
		}
	}
	return result
}

func selectedDigestTargetMembersV1(target string, values map[string]json.RawMessage) []string {
	members := digestTargetMembersV1(target)
	if len(members) <= 1 {
		return members
	}
	var effectKind string
	_ = json.Unmarshal(values["effect_kind"], &effectKind)
	for _, member := range members {
		if effectKind == "PR" && strings.HasPrefix(member, "PR") || effectKind == "MERGE" && strings.HasPrefix(member, "Merge") {
			return []string{member}
		}
	}
	if target == "StageGrantV2-or-PhaseCheckpointV2" {
		var stage string
		_ = json.Unmarshal(values["stage"], &stage)
		if stage == "B_IMPLEMENTATION" || stage == "C_BRANCH_ACCEPTANCE" {
			return []string{"StageGrantV2"}
		}
		return []string{"PhaseCheckpointV2"}
	}
	return members
}

func (context *canonicalPredicateContextV1) digestValidForTarget(target, digest string) bool {
	if context == nil {
		return false
	}
	for _, member := range digestTargetMembersV1(target) {
		if member == "exact-bytes" {
			if len(context.exactBytes) != 0 && digest == sha256Hex(context.exactBytes) {
				return true
			}
			continue
		}
		if positive := context.recordPositiveByType[member]; len(positive) != 0 && digest == sha256Hex(positive) {
			return true
		}
	}
	_, valid := context.validDigestByTarget[target][digest]
	return valid
}

func (context *canonicalPredicateContextV1) firstValidDigest(target string, values map[string]json.RawMessage) (string, bool) {
	if context == nil {
		return "", false
	}
	digests := make([]string, 0)
	for _, member := range selectedDigestTargetMembersV1(target, values) {
		if member == "exact-bytes" {
			if len(context.exactBytes) != 0 {
				digests = append(digests, sha256Hex(context.exactBytes))
			}
			continue
		}
		if positive := context.recordPositiveByType[member]; len(positive) != 0 {
			digests = append(digests, sha256Hex(positive))
		}
	}
	if len(digests) == 0 {
		for digest := range context.validDigestByTarget[target] {
			digests = append(digests, digest)
		}
	}
	sort.Strings(digests)
	if len(digests) == 0 {
		return "", false
	}
	return digests[0], true
}

func (context *canonicalPredicateContextV1) firstForeignDigest(target string) (string, bool) {
	if context == nil {
		return "", false
	}
	targetMembers := make(map[string]struct{})
	for _, member := range digestTargetMembersV1(target) {
		targetMembers[member] = struct{}{}
	}
	digests := make([]string, 0, len(context.recordPositiveByType))
	for recordType, positive := range context.recordPositiveByType {
		if recordType == "exact-bytes" {
			continue
		}
		if _, targetType := targetMembers[recordType]; targetType || len(positive) == 0 {
			continue
		}
		digest := sha256Hex(positive)
		if context.digestValidForTarget(target, digest) {
			continue
		}
		digests = append(digests, digest)
	}
	sort.Strings(digests)
	if len(digests) == 0 {
		return "", false
	}
	return digests[0], true
}

func (context *canonicalPredicateContextV1) digestValidForSelectedTarget(target, digest string, values map[string]json.RawMessage) bool {
	if context == nil {
		return false
	}
	for _, member := range selectedDigestTargetMembersV1(target, values) {
		if member == "exact-bytes" {
			return len(context.exactBytes) != 0 && digest == sha256Hex(context.exactBytes)
		}
		if records := context.recordByTypeAndDigest[member]; records != nil {
			if _, ok := records[digest]; ok {
				return true
			}
		}
	}
	return false
}

func assertFinalTypedReferenceContextV1(catalog CanonicalVectorCatalogV1, prototypes, finals map[string][]byte, context *canonicalPredicateContextV1, prototypeBackedTypes map[string]bool) error {
	for _, entry := range catalog.Entries {
		if entry.RecordName == "ArtifactBlobV1" {
			continue
		}
		values, _, _, err := decodeCanonicalVectorObjectV1(finals[entry.SchemaID])
		if err != nil {
			return err
		}
		for index, field := range entry.Fields {
			if field.DigestTarget == "" || isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
				continue
			}
			raw, present := values[field.FieldPath]
			if !present {
				continue
			}
			candidates := []json.RawMessage{raw}
			if field.JSONType == WireArray && json.Unmarshal(raw, &candidates) != nil {
				return fmt.Errorf("%s.%s final typed-reference array is invalid", entry.SchemaID, field.FieldPath)
			}
			for _, candidate := range candidates {
				var digest string
				if json.Unmarshal(candidate, &digest) != nil || !context.digestValidForSelectedTarget(field.DigestTarget, digest, values) && !frozenExactBytesDigestValidV1(entry, field.FieldPath, digest, values) {
					return fmt.Errorf("%s.%s does not digest exact final emitted target bytes", entry.SchemaID, field.FieldPath)
				}
				for _, member := range selectedDigestTargetMembersV1(field.DigestTarget, values) {
					if member == "exact-bytes" {
						continue
					}
					var prototype []byte
					for _, targetEntry := range catalog.Entries {
						if targetEntry.RecordName == member {
							prototype = prototypes[targetEntry.SchemaID]
							break
						}
					}
					final := context.recordPositiveByType[member]
					if len(prototype) != 0 && !bytes.Equal(prototype, final) && digest == sha256Hex(prototype) && !prototypeBackedTypes[member] {
						return fmt.Errorf("%s.%s retained prototype digest for finalized %s", entry.SchemaID, field.FieldPath, member)
					}
				}
			}
		}
	}
	return nil
}

func applyTypedReferencePositivesV1(entry CanonicalVectorEntryV1, values map[string]json.RawMessage, context *canonicalPredicateContextV1) error {
	for index, field := range entry.Fields {
		if field.DigestTarget == "" || isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
			continue
		}
		raw, present := values[field.FieldPath]
		if !present {
			continue
		}
		digest, ok := context.firstValidDigest(field.DigestTarget, values)
		if !ok {
			return fmt.Errorf("%s.%s cannot establish typed target %s", entry.SchemaID, field.FieldPath, field.DigestTarget)
		}
		encoded := mustMarshalCanonicalVectorStringV1(digest)
		if field.JSONType != WireArray {
			values[field.FieldPath] = encoded
			continue
		}
		var elements []json.RawMessage
		if json.Unmarshal(raw, &elements) != nil {
			return fmt.Errorf("%s.%s typed reference array is invalid", entry.SchemaID, field.FieldPath)
		}
		for elementIndex := range elements {
			elements[elementIndex] = append(json.RawMessage(nil), encoded...)
		}
		if len(elements) > 1 && strings.Contains(field.ValueType, "(set") {
			return fmt.Errorf("%s.%s needs multiple distinct target records", entry.SchemaID, field.FieldPath)
		}
		values[field.FieldPath], _ = json.Marshal(elements)
	}
	return nil
}

func standaloneCanonicalPredicateContextV1(entry CanonicalVectorEntryV1, positive []byte) *canonicalPredicateContextV1 {
	context := newEmptyCanonicalPredicateContextV1()
	context.addRecord(entry.RecordName, positive)
	for index, field := range entry.Fields {
		if field.DigestTarget == "" || isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
			continue
		}
		return nil
	}
	return context
}

func validateCanonicalCatalogPositiveV1(entry CanonicalVectorEntryV1, data []byte, byRecord map[string]CanonicalVectorEntryV1, visiting map[string]bool, context *canonicalPredicateContextV1) error {
	if err := validateCanonicalVectorBytesV1(entry, data, context); err != nil {
		return err
	}
	if entry.RecordName == "ArtifactBlobV1" {
		return nil
	}
	if visiting[entry.SchemaID] {
		return errors.New("record target cycle")
	}
	visiting[entry.SchemaID] = true
	defer delete(visiting, entry.SchemaID)
	values, _, _, err := decodeCanonicalVectorObjectV1(data)
	if err != nil {
		return err
	}
	for _, field := range entry.Fields {
		raw, present := values[field.FieldPath]
		if !present {
			continue
		}
		targetName := field.RecordTarget
		if targetName == "" && field.JSONType == WireArray {
			targetName = arrayElementTypeV1(field.ValueType)
		}
		target, ok := byRecord[targetName]
		if !ok {
			continue
		}
		if field.JSONType == WireObject {
			if err := validateCanonicalCatalogPositiveV1(target, raw, byRecord, visiting, context); err != nil {
				return fmt.Errorf("field %s: %w", field.FieldPath, err)
			}
		}
		if field.JSONType == WireArray {
			var elements []json.RawMessage
			if json.Unmarshal(raw, &elements) != nil {
				return fmt.Errorf("field %s is not an array", field.FieldPath)
			}
			for index, element := range elements {
				if err := validateCanonicalCatalogPositiveV1(target, element, byRecord, visiting, context); err != nil {
					return fmt.Errorf("field %s[%d]: %w", field.FieldPath, index, err)
				}
			}
		}
	}
	return nil
}

type canonicalVectorValidationErrorV1 struct {
	code            CanonicalRequiredError
	path            string
	falsePredicates []string
}

func (e *canonicalVectorValidationErrorV1) Error() string {
	if len(e.falsePredicates) != 0 {
		return fmt.Sprintf("%s: predicates %s", e.code, strings.Join(e.falsePredicates, ","))
	}
	if e.path != "" {
		return fmt.Sprintf("%s: field %s", e.code, e.path)
	}
	return string(e.code)
}

// ValidateCanonicalVectorBytesV1 mechanically validates one record against
// the extracted descriptors and complete frozen predicate set. It is also used
// by generation, so a recipe can never be reported as an executable vector
// unless its bytes actually produce the frozen result class.
func ValidateCanonicalVectorBytesV1(entry CanonicalVectorEntryV1, data []byte) error {
	return validateCanonicalVectorBytesV1(entry, data)
}

// GenerateExecutableCanonicalVectorsV1 materializes and validates the
// positive vector and every rejection recipe carried by an entry.
func GenerateExecutableCanonicalVectorsV1(entry CanonicalVectorEntryV1) (ExecutableCanonicalVectorSetV1, error) {
	positive, err := GenerateMinimalCanonicalVectorV1(entry)
	if err != nil {
		return ExecutableCanonicalVectorSetV1{}, err
	}
	context := standaloneCanonicalPredicateContextV1(entry, positive)
	if context != nil && entry.RecordName != "ArtifactBlobV1" {
		values, _, _, decodeErr := decodeCanonicalVectorObjectV1(positive)
		if decodeErr != nil {
			return ExecutableCanonicalVectorSetV1{}, decodeErr
		}
		if err := applyTypedReferencePositivesV1(entry, values, context); err != nil {
			return ExecutableCanonicalVectorSetV1{}, err
		}
		if err := applyPositivePredicatesV1(entry, values); err != nil {
			return ExecutableCanonicalVectorSetV1{}, err
		}
		if err := applyEd25519VectorsV1(entry, values); err != nil {
			return ExecutableCanonicalVectorSetV1{}, err
		}
		for index, field := range entry.Fields {
			if !isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
				continue
			}
			preimage, err := marshalCanonicalVectorObjectV1(entry.Fields, values, field.FieldPath)
			if err != nil {
				return ExecutableCanonicalVectorSetV1{}, err
			}
			values[field.FieldPath] = mustMarshalCanonicalVectorStringV1(sha256Hex(preimage))
		}
		positive, err = marshalCanonicalVectorObjectV1(entry.Fields, values, "")
		if err != nil {
			return ExecutableCanonicalVectorSetV1{}, err
		}
	}
	return generateExecutableCanonicalVectorsFromPositiveV1(entry, positive, nil, context)
}

// GenerateExecutableCanonicalCatalogVectorsV1 materializes the complete
// frozen catalog. Every rejection starts from the recursively materialized
// positive for that exact entry, including record-valued fields and record
// array elements; the descriptor-only minimal object is never used as a
// rejection base for this path.
func GenerateExecutableCanonicalCatalogVectorsV1(catalog CanonicalVectorCatalogV1) (map[string]ExecutableCanonicalVectorSetV1, error) {
	positives, context, err := generateCanonicalCatalogPositiveVectorsV1(catalog)
	if err != nil {
		return nil, err
	}
	result := make(map[string]ExecutableCanonicalVectorSetV1, len(catalog.Entries))
	positiveByRecord := make(map[string][]byte, len(catalog.Entries))
	for _, entry := range catalog.Entries {
		positiveByRecord[entry.RecordName] = positives[entry.SchemaID]
	}
	for _, entry := range catalog.Entries {
		vectors, err := generateExecutableCanonicalVectorsFromPositiveV1(entry, positives[entry.SchemaID], positiveByRecord, context)
		if err != nil {
			return nil, fmt.Errorf("materialize %s executable vectors: %w", entry.SchemaID, err)
		}
		result[entry.SchemaID] = vectors
	}
	return result, nil
}

func generateExecutableCanonicalVectorsFromPositiveV1(entry CanonicalVectorEntryV1, positive []byte, recordPositives map[string][]byte, context *canonicalPredicateContextV1) (ExecutableCanonicalVectorSetV1, error) {
	if err := validateCanonicalVectorBytesV1(entry, positive, context); err != nil {
		return ExecutableCanonicalVectorSetV1{}, fmt.Errorf("positive vector for %s is invalid: %w", entry.SchemaID, err)
	}
	result := ExecutableCanonicalVectorSetV1{SchemaID: entry.SchemaID, Positive: append([]byte(nil), positive...), Rejections: make([]ExecutableCanonicalVectorV1, 0, len(entry.Rejections))}
	for _, recipe := range entry.Rejections {
		mutated, err := mutateCanonicalVectorV1(entry, positive, recipe, recordPositives, context)
		if err != nil {
			return ExecutableCanonicalVectorSetV1{}, fmt.Errorf("generate %s: %w", recipe.VectorID, err)
		}
		if strings.Contains(recipe.Mutation, "PREDICATE_") {
			if recipe.RequiredError != CanonicalPredicateInvalid {
				return ExecutableCanonicalVectorSetV1{}, fmt.Errorf("vector %s has predicate mutation with error class %s", recipe.VectorID, recipe.RequiredError)
			}
			_, descriptorErr := validateCanonicalVectorDescriptorConstraintsV1(entry, mutated)
			if descriptorErr != nil {
				predicateID := strings.TrimPrefix(recipe.Mutation, "PREDICATE_")
				predicate, _ := canonicalVectorPredicateV1(entry.Predicates, predicateID)
				return ExecutableCanonicalVectorSetV1{}, fmt.Errorf("vector %s (%s paths=%v arguments=%v) violates a descriptor constraint: %w", recipe.VectorID, predicate.Operator, predicate.FieldPaths, predicate.Arguments, descriptorErr)
			}
			target := strings.TrimPrefix(recipe.Mutation, "PREDICATE_")
			falseIDs, err := falseCanonicalPredicatesForMutationV1(entry, positive, mutated, target, context)
			if err != nil {
				return ExecutableCanonicalVectorSetV1{}, fmt.Errorf("vector %s does not prove its expected predicate classification: %w", recipe.VectorID, err)
			}
			result.Rejections = append(result.Rejections, ExecutableCanonicalVectorV1{
				VectorID: recipe.VectorID, Bytes: mutated, RequiredError: recipe.RequiredError, FalsePredicateIDs: falseIDs,
			})
			continue
		}
		validationErr := validateCanonicalVectorBytesV1(entry, mutated, context)
		var classified *canonicalVectorValidationErrorV1
		if !errors.As(validationErr, &classified) || classified.code != recipe.RequiredError {
			return ExecutableCanonicalVectorSetV1{}, fmt.Errorf("vector %s classified as %v, want %s", recipe.VectorID, validationErr, recipe.RequiredError)
		}
		falseIDs := append([]string(nil), classified.falsePredicates...)
		sort.Strings(falseIDs)
		result.Rejections = append(result.Rejections, ExecutableCanonicalVectorV1{
			VectorID: recipe.VectorID, Bytes: mutated, RequiredError: recipe.RequiredError, FalsePredicateIDs: falseIDs,
		})
	}
	return result, nil
}

func falseCanonicalPredicatesForMutationV1(entry CanonicalVectorEntryV1, positive, mutated []byte, target string, context *canonicalPredicateContextV1) ([]string, error) {
	if err := validateCanonicalVectorBytesV1(entry, positive, context); err != nil {
		return nil, fmt.Errorf("positive validation: %w", err)
	}
	mutatedValues, err := validateCanonicalVectorDescriptorConstraintsV1(entry, mutated)
	if err != nil {
		return nil, fmt.Errorf("mutated descriptor validation: %w", err)
	}
	falseIDs := falseCanonicalPredicatesV1(entry, mutatedValues, context)
	if _, found := canonicalVectorPredicateV1(entry.Predicates, target); !found {
		return nil, fmt.Errorf("target predicate %s is absent", target)
	}
	if !containsCanonicalVectorStringV1(falseIDs, target) {
		predicate, _ := canonicalVectorPredicateV1(entry.Predicates, target)
		return nil, fmt.Errorf("target predicate %s (%s paths=%v arguments=%v) remained true", target, predicate.Operator, predicate.FieldPaths, predicate.Arguments)
	}
	validationErr := validateCanonicalVectorBytesV1(entry, mutated, context)
	var classified *canonicalVectorValidationErrorV1
	if !errors.As(validationErr, &classified) || classified.code != CanonicalPredicateInvalid {
		return nil, fmt.Errorf("mutation classified as %v, want %s", validationErr, CanonicalPredicateInvalid)
	}
	actual := append([]string(nil), classified.falsePredicates...)
	sort.Strings(actual)
	if !equalVectorStringsV1(actual, falseIDs) {
		return nil, fmt.Errorf("validator false predicates %v, evaluator produced %v", actual, falseIDs)
	}
	return falseIDs, nil
}

func validateCanonicalVectorBytesV1(entry CanonicalVectorEntryV1, data []byte, contexts ...*canonicalPredicateContextV1) error {
	var context *canonicalPredicateContextV1
	if len(contexts) != 0 {
		context = contexts[0]
	}
	if entry.RecordName == "ArtifactBlobV1" && entry.SchemaID == "artifact-blob-v1" {
		if len(data) >= 1 && len(data) <= 33554432 {
			return nil
		}
		return &canonicalVectorValidationErrorV1{code: CanonicalBoundInvalid}
	}
	if !utf8.Valid(data) || len(data) == 0 || len(data) > 1<<20 {
		return &canonicalVectorValidationErrorV1{code: CanonicalNonCanonical}
	}
	values, err := validateCanonicalVectorDescriptorConstraintsV1(entry, data)
	if err != nil {
		return err
	}
	falsePredicates := falseCanonicalPredicatesV1(entry, values, context)
	for fieldIndex, field := range entry.Fields {
		if !isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, fieldIndex) {
			continue
		}
		var actual string
		if json.Unmarshal(values[field.FieldPath], &actual) != nil {
			return &canonicalVectorValidationErrorV1{code: CanonicalTypeInvalid, path: field.FieldPath}
		}
		preimage, err := marshalCanonicalVectorObjectV1(entry.Fields, values, field.FieldPath)
		if err != nil || actual != sha256Hex(preimage) {
			if len(falsePredicates) != 0 {
				return &canonicalVectorValidationErrorV1{code: CanonicalPredicateInvalid, falsePredicates: falsePredicates}
			}
			return &canonicalVectorValidationErrorV1{code: CanonicalDigestInvalid, path: field.FieldPath}
		}
	}
	if len(falsePredicates) != 0 {
		return &canonicalVectorValidationErrorV1{code: CanonicalPredicateInvalid, falsePredicates: falsePredicates}
	}
	return nil
}

func validateCanonicalVectorDescriptorConstraintsV1(entry CanonicalVectorEntryV1, data []byte) (map[string]json.RawMessage, error) {
	values, order, duplicate, parseErr := decodeCanonicalVectorObjectV1(data)
	if parseErr != nil {
		return nil, &canonicalVectorValidationErrorV1{code: CanonicalNonCanonical}
	}
	if duplicate {
		return nil, &canonicalVectorValidationErrorV1{code: CanonicalDuplicateField}
	}
	descriptors := make(map[string]WireFieldDescriptorV1, len(entry.Fields))
	for _, field := range entry.Fields {
		descriptors[field.FieldPath] = field
	}
	for _, name := range order {
		if _, ok := descriptors[name]; !ok {
			return nil, &canonicalVectorValidationErrorV1{code: CanonicalUnknownField}
		}
	}
	expectedOrder := make([]string, 0, len(entry.Fields))
	for _, field := range entry.Fields {
		_, present := values[field.FieldPath]
		if !present && !field.Optional {
			return nil, &canonicalVectorValidationErrorV1{code: CanonicalMissingField}
		}
		if present {
			expectedOrder = append(expectedOrder, field.FieldPath)
		}
	}
	if !equalVectorStringsV1(order, expectedOrder) {
		return nil, &canonicalVectorValidationErrorV1{code: CanonicalNonCanonical}
	}
	canonical, err := marshalCanonicalVectorObjectV1(entry.Fields, values, "")
	if err != nil || !bytes.Equal(canonical, data) {
		return nil, &canonicalVectorValidationErrorV1{code: CanonicalNonCanonical}
	}
	for _, field := range entry.Fields {
		raw, present := values[field.FieldPath]
		if !present {
			continue
		}
		if code := validateCanonicalDescriptorValueV1(field, raw); code != "" {
			return nil, &canonicalVectorValidationErrorV1{code: code, path: field.FieldPath}
		}
	}
	return values, nil
}

func equalVectorStringsV1(left, right []string) bool {
	if len(left) != len(right) {
		return false
	}
	for index := range left {
		if left[index] != right[index] {
			return false
		}
	}
	return true
}

func decodeCanonicalVectorObjectV1(data []byte) (map[string]json.RawMessage, []string, bool, error) {
	decoder := json.NewDecoder(bytes.NewReader(data))
	token, err := decoder.Token()
	if err != nil || token != json.Delim('{') {
		return nil, nil, false, errors.New("record is not an object")
	}
	values := make(map[string]json.RawMessage)
	var order []string
	duplicate := false
	for decoder.More() {
		nameToken, err := decoder.Token()
		if err != nil {
			return nil, nil, false, err
		}
		name, ok := nameToken.(string)
		if !ok {
			return nil, nil, false, errors.New("field name is not a string")
		}
		var raw json.RawMessage
		if err := decoder.Decode(&raw); err != nil {
			return nil, nil, false, err
		}
		if _, exists := values[name]; exists {
			duplicate = true
		}
		values[name] = append(json.RawMessage(nil), raw...)
		order = append(order, name)
	}
	if token, err = decoder.Token(); err != nil || token != json.Delim('}') {
		return nil, nil, false, errors.New("record is unterminated")
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return nil, nil, false, errors.New("record has trailing JSON")
	}
	return values, order, duplicate, nil
}

func validateCanonicalDescriptorValueV1(field WireFieldDescriptorV1, raw json.RawMessage) CanonicalRequiredError {
	if bytes.Equal(raw, []byte("null")) {
		return CanonicalTypeInvalid
	}
	switch field.JSONType {
	case WireString:
		var value string
		if json.Unmarshal(raw, &value) != nil {
			return CanonicalTypeInvalid
		}
		if field.MinBytes != nil && uint64(len(value)) < *field.MinBytes || field.MaxBytes != nil && uint64(len(value)) > *field.MaxBytes {
			return CanonicalBoundInvalid
		}
		if isClosedEnumType(field.ValueType) || strings.HasPrefix(field.ValueType, "{") {
			if err := ValidatePrimitiveWireValueV1(field.ValueType, value); err != nil {
				return CanonicalEnumInvalid
			}
		}
		var primitiveErr error
		if strings.HasPrefix(field.ValueType, "sha256<") || field.ValueType == "blob256" {
			primitiveErr = validateExactLowerHex(value, 64)
		} else {
			primitiveErr = ValidatePrimitiveWireValueV1(field.ValueType, value)
		}
		if primitiveErr != nil {
			if field.ValueType == "absPath" && strings.HasPrefix(value, "/") && strings.Contains(value, "/../") {
				return CanonicalNonCanonical
			}
			return CanonicalBoundInvalid
		}
	case WireInteger:
		var value uint64
		if json.Unmarshal(raw, &value) != nil {
			return CanonicalTypeInvalid
		}
		if field.MinU64 != nil && value < *field.MinU64 || field.MaxU64 != nil && value > *field.MaxU64 {
			return CanonicalBoundInvalid
		}
	case WireBoolean:
		var value bool
		if json.Unmarshal(raw, &value) != nil {
			return CanonicalTypeInvalid
		}
	case WireArray:
		var values []json.RawMessage
		if json.Unmarshal(raw, &values) != nil {
			return CanonicalTypeInvalid
		}
		if field.MinItems != nil && uint64(len(values)) < *field.MinItems || field.MaxItems != nil && uint64(len(values)) > *field.MaxItems {
			return CanonicalBoundInvalid
		}
		if strings.Contains(field.ValueType, "(set") {
			for index := 1; index < len(values); index++ {
				comparison := bytes.Compare(values[index-1], values[index])
				if comparison >= 0 {
					return CanonicalOrderInvalid
				}
			}
		}
		elementType := arrayElementTypeV1(field.ValueType)
		if elementType != "" && !(strings.HasSuffix(elementType, "V1") || strings.HasSuffix(elementType, "V2") || strings.HasSuffix(elementType, "V3") || strings.HasSuffix(elementType, "V4")) {
			descriptor, err := ResolveWireFieldDescriptorV1(field.SchemaID, field.FieldPath, field.Ordinal, elementType, false)
			if err != nil {
				return CanonicalTypeInvalid
			}
			for _, value := range values {
				if code := validateCanonicalDescriptorValueV1(descriptor, value); code != "" {
					return code
				}
			}
		}
	case WireObject:
		if len(raw) == 0 || raw[0] != '{' || !json.Valid(raw) {
			return CanonicalTypeInvalid
		}
	case WireRawJSON:
		if !json.Valid(raw) || len(raw) == 0 || raw[0] != '{' && raw[0] != '[' {
			return CanonicalTypeInvalid
		}
		if field.MinBytes != nil && uint64(len(raw)) < *field.MinBytes || field.MaxBytes != nil && uint64(len(raw)) > *field.MaxBytes {
			return CanonicalBoundInvalid
		}
	default:
		return CanonicalTypeInvalid
	}
	return ""
}

func sha256Hex(data []byte) string {
	digest := sha256.Sum256(data)
	return hex.EncodeToString(digest[:])
}

func falseCanonicalPredicatesV1(entry CanonicalVectorEntryV1, values map[string]json.RawMessage, contexts ...*canonicalPredicateContextV1) []string {
	var context *canonicalPredicateContextV1
	if len(contexts) != 0 {
		context = contexts[0]
	}
	fields := make(map[string]WireFieldDescriptorV1, len(entry.Fields))
	for _, field := range entry.Fields {
		fields[field.FieldPath] = field
	}
	var result []string
	for _, predicate := range entry.Predicates {
		if !canonicalPredicateValidV1(entry, predicate, fields, values, context) {
			result = append(result, predicate.PredicateID)
		}
	}
	sort.Strings(result)
	return result
}

func finalizedCanonicalPredicateValuesV1(entry CanonicalVectorEntryV1, context *canonicalPredicateContextV1) map[string]json.RawMessage {
	if context == nil {
		return nil
	}
	record := context.recordPositiveByType[entry.RecordName]
	values, _, duplicate, err := decodeCanonicalVectorObjectV1(record)
	if err != nil || duplicate {
		return nil
	}
	return values
}

func canonicalPredicateValidV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, fields map[string]WireFieldDescriptorV1, values map[string]json.RawMessage, context *canonicalPredicateContextV1) bool {
	paths, operandErr := resolveCanonicalPredicateOperandPathsV1(entry, predicate, fields)
	if valid, handled := frozenCanonicalPredicateValidV1(entry, predicate, paths, fields, values, context); handled {
		return valid
	}
	if operandErr != nil {
		return false
	}
	switch predicate.Operator {
	case PredicateExactLiteral:
		if len(predicate.FieldPaths) != 1 || len(predicate.Arguments) == 0 {
			return false
		}
		raw, present := values[predicate.FieldPaths[0]]
		field, found := fields[predicate.FieldPaths[0]]
		if !present || !found {
			return false
		}
		switch field.JSONType {
		case WireString:
			var scalar string
			return json.Unmarshal(raw, &scalar) == nil && scalar == predicate.Arguments[0]
		case WireInteger, WireBoolean, WireArray:
			return string(raw) == predicate.Arguments[0]
		default:
			return false
		}
	case PredicateAllEqual:
		if len(paths) < 2 {
			return false
		}
		first, present := values[paths[0]]
		if !present {
			return false
		}
		for _, path := range paths[1:] {
			if next, ok := values[path]; !ok || !bytes.Equal(first, next) {
				return false
			}
		}
		return true
	case PredicateIfAndOnlyIf, PredicateImplies:
		if valid, handled := frozenImplicationPredicateV1(entry, predicate, values); handled {
			return valid
		}
		if len(paths) < 2 {
			return false
		}
		antecedent, antecedentOK := canonicalPredicateConditionV1(paths[0], fields, values)
		consequent, consequentOK := canonicalPredicateConditionV1(paths[1], fields, values)
		if !antecedentOK || !consequentOK {
			return false
		}
		if predicate.Operator == PredicateIfAndOnlyIf {
			return antecedent == consequent
		}
		return !antecedent || consequent
	case PredicateExactlyOne:
		count := 0
		for _, path := range paths {
			if _, present := values[path]; present {
				count++
			}
		}
		return count == 1
	case PredicateSubset:
		if len(paths) < 2 {
			return false
		}
		var subset, superset []json.RawMessage
		if json.Unmarshal(values[paths[0]], &subset) != nil || json.Unmarshal(values[paths[1]], &superset) != nil {
			return false
		}
		members := make(map[string]struct{}, len(superset))
		for _, value := range superset {
			members[string(value)] = struct{}{}
		}
		for _, value := range subset {
			if _, found := members[string(value)]; !found {
				return false
			}
		}
		return true
	case PredicateOrdinalSuccess:
		if len(paths) < 2 {
			return false
		}
		var predecessor, successor uint64
		return json.Unmarshal(values[paths[0]], &predecessor) == nil && json.Unmarshal(values[paths[1]], &successor) == nil && predecessor != ^uint64(0) && successor == predecessor+1
	case PredicateStateTransition:
		return frozenStatePredicateV1(entry, predicate, paths, values)
	case PredicateTypedReference:
		if len(paths) == 0 || context == nil {
			return false
		}
		for _, path := range paths {
			raw, present := values[path]
			field := fields[path]
			if !present && field.Optional {
				continue
			}
			if !present || field.DigestTarget == "" {
				return false
			}
			candidates := []json.RawMessage{raw}
			if field.JSONType == WireArray {
				candidates = nil
				if json.Unmarshal(raw, &candidates) != nil {
					return false
				}
			}
			for _, candidate := range candidates {
				var digest string
				if json.Unmarshal(candidate, &digest) != nil {
					return false
				}
				if context.digestValidForSelectedTarget(field.DigestTarget, digest, values) || frozenExactBytesDigestValidV1(entry, path, digest, values) {
					continue
				}
				return false
			}
		}
		return true
	case PredicateDigestPreimage:
		return frozenDigestPreimagePredicateV1(entry, predicate, values, finalizedCanonicalPredicateValuesV1(entry, context))
	case PredicateDerivation:
		return false
	case PredicateAggregateLEQ:
		if len(paths) < 2 {
			return false
		}
		var sum uint64
		for _, path := range paths[:len(paths)-1] {
			var addend uint64
			if json.Unmarshal(values[path], &addend) != nil || ^uint64(0)-sum < addend {
				return false
			}
			sum += addend
		}
		var limit uint64
		return json.Unmarshal(values[paths[len(paths)-1]], &limit) == nil && sum <= limit
	default:
		return false
	}
}

func frozenExactBytesDigestValidV1(entry CanonicalVectorEntryV1, path, digest string, values map[string]json.RawMessage) bool {
	if path == "probe_result_sha256" {
		expected, handled := absenceProbeResultDigestV1(entry.SchemaID, values)
		return handled && expected == digest
	}
	if path == "commitment_sha256" {
		commitment, present := values["commitment"]
		return present && digest == sha256Hex(commitment)
	}
	return false
}

func canonicalPredicateConditionV1(path string, fields map[string]WireFieldDescriptorV1, values map[string]json.RawMessage) (bool, bool) {
	actual, present := values[path]
	field, ok := fields[path]
	if !ok {
		return false, false
	}
	if field.JSONType == WireBoolean && present {
		return bytes.Equal(actual, []byte("true")), true
	}
	if field.Optional {
		return present, true
	}
	return false, false
}

func frozenCanonicalPredicateValidV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, paths []string, fields map[string]WireFieldDescriptorV1, values map[string]json.RawMessage, context *canonicalPredicateContextV1) (bool, bool) {
	switch predicate.PredicateID {
	case "P-DIFF-002":
		return frozenStageDiffAuthorityValidV1(values, context), true
	case "P-PARENT-001":
		return frozenCheckpointParentProjectionValidV1(values, context), true
	}
	if predicate.PredicateID == "P-EVENT-001" && entry.RecordName != "EffectLedgerEventPreimageV1" {
		expected := finalizedCanonicalPredicateValuesV1(entry, context)
		actual, present := values["event_id"]
		want, expectedPresent := expected["event_id"]
		return present == expectedPresent && (!present || bytes.Equal(actual, want)), true
	}
	if predicate.Operator == PredicateDerivation {
		if _, crossRecord := frozenCrossRecordPredicateIDsV1[predicate.PredicateID]; !crossRecord {
			return frozenDerivationPredicateValidV1(predicate, values, context), true
		}
	}
	if predicate.Operator == PredicateAggregateLEQ && predicate.PredicateID == "P-RESOURCE-001" {
		expected, err := materializedResourceProfileValuesV1(values, context)
		if err != nil {
			return false, true
		}
		for path, want := range expected {
			actual, present := values[path]
			if !present || !bytes.Equal(actual, want) {
				return false, true
			}
		}
		for _, optional := range []string{"container_image_sha256"} {
			_, actual := values[optional]
			_, wanted := expected[optional]
			if actual != wanted {
				return false, true
			}
		}
		return true, true
	}
	if predicate.Operator == PredicateStateTransition {
		switch predicate.PredicateID {
		case "P-BARRIER-001", "P-EVENT-001", "P-BARRIER-008", "P-PUBLISHER-006", "P-predecessor-writer-lease-v1-ROW-001", "P-RESOURCE-002":
			return frozenStatePredicateV1(entry, predicate, paths, values), true
		}
	}
	if predicate.Operator == PredicateIfAndOnlyIf || predicate.Operator == PredicateImplies {
		if valid, handled := frozenImplicationPredicateV1(entry, predicate, values); handled {
			return valid, true
		}
	}
	if _, compatible := frozenCrossRecordPredicateIDsV1[predicate.PredicateID]; compatible {
		expected := finalizedCanonicalPredicateValuesV1(entry, context)
		path := frozenCrossRecordMutationPathV1(entry, predicate, paths, fields)
		if path == "" {
			return false, true
		}
		actual, present := values[path]
		want, expectedPresent := expected[path]
		return present == expectedPresent && (!present || bytes.Equal(actual, want)), true
	}
	return false, false
}

func frozenStageDiffAuthorityValidV1(values map[string]json.RawMessage, context *canonicalPredicateContextV1) bool {
	if context == nil {
		return false
	}
	var stage, authorityDigest string
	if json.Unmarshal(values["stage"], &stage) != nil || json.Unmarshal(values["derivation_authority_sha256"], &authorityDigest) != nil {
		return false
	}
	authorityType := "PhaseCheckpointV2"
	if stage == "B_IMPLEMENTATION" || stage == "C_BRANCH_ACCEPTANCE" {
		authorityType = "StageGrantV2"
	}
	authorityBytes, ok := context.recordForDigest(authorityType, authorityDigest)
	if !ok {
		return false
	}
	authority, _, duplicate, err := decodeCanonicalVectorObjectV1(authorityBytes)
	if err != nil || duplicate {
		return false
	}
	compare := func(lineagePath, authorityPath string) bool {
		actual, actualPresent := values[lineagePath]
		expected, expectedPresent := authority[authorityPath]
		return actualPresent && expectedPresent && bytes.Equal(actual, expected)
	}
	switch stage {
	case "B_IMPLEMENTATION":
		return compare("base_oid", "base_sha")
	case "C_BRANCH_ACCEPTANCE":
		return compare("base_oid", "base_sha") && compare("candidate_oid", "candidate_sha")
	case "INTEGRATION_ACCEPTANCE":
		return compare("base_oid", "integration_base_oid") && compare("candidate_oid", "candidate_sha")
	case "POST_MERGE_ACCEPTANCE":
		return compare("base_oid", "premerge_base_oid") && compare("candidate_oid", "merge_result_oid")
	default:
		return false
	}
}

func frozenCheckpointParentProjectionValidV1(values map[string]json.RawMessage, context *canonicalPredicateContextV1) bool {
	if context == nil {
		return false
	}
	checkpointBytes := context.recordPositiveByType["PhaseCheckpointV2"]
	checkpoint, _, duplicate, err := decodeCanonicalVectorObjectV1(checkpointBytes)
	if err != nil || duplicate {
		return false
	}
	compared := 0
	for path, actual := range values {
		if path == "next_stage_grant_sha256" || path == "checkpoint_sha256" {
			return false
		}
		expected, present := checkpoint[path]
		if !present || !bytes.Equal(actual, expected) {
			return false
		}
		compared++
	}
	for path := range checkpoint {
		if path == "next_stage_grant_sha256" || path == "checkpoint_sha256" {
			continue
		}
		if _, present := values[path]; !present {
			return false
		}
	}
	return compared != 0
}

func applyFrozenCrossRecordPositiveV1(predicate PredicateDescriptorV1, values map[string]json.RawMessage, context *canonicalPredicateContextV1) error {
	switch predicate.PredicateID {
	case "P-PARENT-001":
		checkpointBytes := context.recordPositiveByType["PhaseCheckpointV2"]
		checkpoint, _, duplicate, err := decodeCanonicalVectorObjectV1(checkpointBytes)
		if err != nil || duplicate {
			return errors.New("P-PARENT-001 has no exact finalized checkpoint")
		}
		for path := range values {
			if path == "next_stage_grant_sha256" || path == "checkpoint_sha256" {
				return fmt.Errorf("P-PARENT-001 projection contains forbidden field %s", path)
			}
			value, present := checkpoint[path]
			if !present {
				delete(values, path)
				continue
			}
			values[path] = append(json.RawMessage(nil), value...)
		}
		for path, value := range checkpoint {
			if path == "next_stage_grant_sha256" || path == "checkpoint_sha256" {
				continue
			}
			if _, known := values[path]; known {
				values[path] = append(json.RawMessage(nil), value...)
			}
		}
	case "P-DIFF-002":
		var stage, digest string
		if json.Unmarshal(values["stage"], &stage) != nil || json.Unmarshal(values["derivation_authority_sha256"], &digest) != nil {
			return errors.New("P-DIFF-002 has unresolved stage authority")
		}
		authorityType := "PhaseCheckpointV2"
		if stage == "B_IMPLEMENTATION" || stage == "C_BRANCH_ACCEPTANCE" {
			authorityType = "StageGrantV2"
		}
		record, ok := context.recordForDigest(authorityType, digest)
		if !ok {
			return errors.New("P-DIFF-002 authority record is unavailable")
		}
		authority, _, _, err := decodeCanonicalVectorObjectV1(record)
		if err != nil {
			return err
		}
		copyField := func(destination, source string) error {
			value, present := authority[source]
			if !present {
				return fmt.Errorf("P-DIFF-002 authority omits %s", source)
			}
			values[destination] = append(json.RawMessage(nil), value...)
			return nil
		}
		switch stage {
		case "B_IMPLEMENTATION":
			return copyField("base_oid", "base_sha")
		case "C_BRANCH_ACCEPTANCE":
			if err := copyField("base_oid", "base_sha"); err != nil {
				return err
			}
			if _, present := authority["candidate_sha"]; present {
				return copyField("candidate_oid", "candidate_sha")
			}
		case "INTEGRATION_ACCEPTANCE":
			if err := copyField("base_oid", "integration_base_oid"); err != nil {
				return err
			}
			return copyField("candidate_oid", "candidate_sha")
		case "POST_MERGE_ACCEPTANCE":
			if err := copyField("base_oid", "premerge_base_oid"); err != nil {
				return err
			}
			return copyField("candidate_oid", "merge_result_oid")
		default:
			return errors.New("P-DIFF-002 stage is not frozen")
		}
	}
	return nil
}

var resourceSummedFieldsV1 = []string{
	"process_memory_bytes", "process_pids", "process_cpu_micros_per_period", "nofile", "wall_ms", "stdout_bytes", "stderr_bytes",
	"evidence_bytes", "transient_bytes", "cache_bytes", "container_memory_bytes", "container_pids", "container_cpu_micros_per_period",
	"container_tmpfs_bytes", "container_shm_bytes", "container_log_bytes", "container_writable_layer_bytes", "docker_daemon_memory_bytes",
	"docker_daemon_pids", "docker_daemon_cpu_micros_per_period", "docker_daemon_cache_bytes", "docker_daemon_log_bytes",
}

var resourcePeriodFieldsV1 = []string{
	"process_cpu_period_micros", "container_cpu_period_micros", "docker_daemon_cpu_period_micros",
}

func materializedResourceProfileValuesV1(values map[string]json.RawMessage, context *canonicalPredicateContextV1) (map[string]json.RawMessage, error) {
	if context == nil {
		return nil, errors.New("P-RESOURCE-001 has no finalized component context")
	}
	var digests []string
	if json.Unmarshal(values["component_profile_sha256s"], &digests) != nil || len(digests) == 0 {
		return nil, errors.New("P-RESOURCE-001 has no component digests")
	}
	components := make([]map[string]json.RawMessage, 0, len(digests))
	for _, digest := range digests {
		record, ok := context.recordForDigest("ResourceProfileV1", digest)
		if !ok {
			return nil, fmt.Errorf("P-RESOURCE-001 component %s is unavailable", digest)
		}
		component, _, duplicate, err := decodeCanonicalVectorObjectV1(record)
		if err != nil || duplicate {
			return nil, fmt.Errorf("P-RESOURCE-001 component %s is not canonical", digest)
		}
		components = append(components, component)
	}
	expected := make(map[string]json.RawMessage)
	for _, path := range resourceSummedFieldsV1 {
		var sum uint64
		for _, component := range components {
			var addend uint64
			if json.Unmarshal(component[path], &addend) != nil || ^uint64(0)-sum < addend {
				return nil, fmt.Errorf("P-RESOURCE-001 %s component sum overflows", path)
			}
			sum += addend
		}
		expected[path] = []byte(strconv.FormatUint(sum, 10))
	}
	for _, path := range resourcePeriodFieldsV1 {
		var period uint64
		for _, component := range components {
			var candidate uint64
			if json.Unmarshal(component[path], &candidate) != nil {
				return nil, fmt.Errorf("P-RESOURCE-001 %s component is invalid", path)
			}
			if candidate == 0 {
				continue
			}
			if period != 0 && candidate != period {
				return nil, fmt.Errorf("P-RESOURCE-001 %s components disagree", path)
			}
			period = candidate
		}
		expected[path] = []byte(strconv.FormatUint(period, 10))
	}
	containerDemandFields := []string{
		"container_memory_bytes", "container_pids", "container_cpu_micros_per_period", "container_cpu_period_micros",
		"container_tmpfs_bytes", "container_shm_bytes", "container_log_bytes", "container_writable_layer_bytes",
	}
	hasContainerDemand, allContainerReadOnly := false, true
	var image string
	secrets := make(map[string]struct{})
	networks := make(map[string]struct{})
	for _, component := range components {
		bearing := false
		for _, path := range containerDemandFields {
			var value uint64
			if json.Unmarshal(component[path], &value) != nil {
				return nil, fmt.Errorf("P-RESOURCE-001 %s container demand is invalid", path)
			}
			bearing = bearing || value != 0
		}
		var componentImage string
		if raw, present := component["container_image_sha256"]; present {
			if json.Unmarshal(raw, &componentImage) != nil || componentImage == "" {
				return nil, errors.New("P-RESOURCE-001 component image is invalid")
			}
			bearing = true
			if image != "" && componentImage != image {
				return nil, errors.New("P-RESOURCE-001 component images are incompatible")
			}
			image = componentImage
		}
		var readOnly bool
		if json.Unmarshal(component["container_read_only_root"], &readOnly) != nil {
			return nil, errors.New("P-RESOURCE-001 component read-only-root is invalid")
		}
		if bearing {
			hasContainerDemand = true
			allContainerReadOnly = allContainerReadOnly && readOnly
		}
		for path, union := range map[string]map[string]struct{}{"secret_capability": secrets, "network_policy": networks} {
			var member string
			if json.Unmarshal(component[path], &member) != nil || member == "" {
				return nil, fmt.Errorf("P-RESOURCE-001 component %s is invalid", path)
			}
			union[member] = struct{}{}
		}
	}
	if image != "" {
		expected["container_image_sha256"] = mustMarshalCanonicalVectorStringV1(image)
	}
	expected["container_read_only_root"] = []byte(strconv.FormatBool(hasContainerDemand && allContainerReadOnly))
	if len(networks) > 1 {
		if _, denyAll := networks["DENY_ALL"]; denyAll {
			return nil, errors.New("P-RESOURCE-001 DENY_ALL network is incompatible with another policy")
		}
	}
	unionJSON := func(union map[string]struct{}, removeNone bool) json.RawMessage {
		if removeNone && len(union) > 1 {
			delete(union, "NONE")
		}
		members := make([]string, 0, len(union))
		for member := range union {
			members = append(members, member)
		}
		sort.Strings(members)
		encoded, _ := json.Marshal(members)
		return encoded
	}
	expected["secret_capabilities"] = unionJSON(secrets, true)
	expected["network_policies"] = unionJSON(networks, true)
	return expected, nil
}

