func frozenDerivationPredicateValidV1(predicate PredicateDescriptorV1, values map[string]json.RawMessage, context *canonicalPredicateContextV1) bool {
	stringValue := func(path string) string {
		var value string
		_ = json.Unmarshal(values[path], &value)
		return value
	}
	switch predicate.PredicateID {
	case "P-DIFF-001":
		rules := map[string]string{
			"B_IMPLEMENTATION":       "B_GRANT_BASE_TO_B_CANDIDATE",
			"C_BRANCH_ACCEPTANCE":    "C_GRANT_BASE_TO_UNCHANGED_C_CANDIDATE",
			"INTEGRATION_ACCEPTANCE": "INTEGRATION_BASE_TO_INTEGRATED_HEAD",
			"POST_MERGE_ACCEPTANCE":  "PREMERGE_BASE_TO_MERGE_RESULT",
		}
		return stringValue("derivation_rule") == rules[stringValue("stage")]
	case "P-github-repository-observation-v1-ROW-001":
		permission := stringValue("permission")
		return permission == "WRITE" || permission == "MAINTAIN" || permission == "ADMIN"
	case "P-effect-pre-call-closure-v1-ROW-001":
		if context == nil {
			return false
		}
		prefix := "Merge"
		if stringValue("effect_kind") == "PR" {
			prefix = "PR"
		}
		for path, target := range map[string]string{
			"intent_sha256": prefix + "EffectIntentV1", "claim_sha256": prefix + "EffectClaimV1", "provider_request_sha256": prefix + "EffectRequestV1",
		} {
			var digest string
			if json.Unmarshal(values[path], &digest) != nil {
				return false
			}
			positive := context.recordPositiveByType[target]
			if len(positive) == 0 || digest != sha256Hex(positive) {
				return false
			}
		}
		return true
	case "P-PR-002":
		_, number := values["pr_number"]
		_, node := values["pr_node_id"]
		mode := stringValue("mutation_mode")
		return !number && !node && mode == "CREATE" || number && node && mode == "UPDATE"
	case "P-MERGE-003":
		var requests, responses []json.RawMessage
		if json.Unmarshal(values["observation_read_request_sha256s"], &requests) != nil || json.Unmarshal(values["observation_read_response_sha256s"], &responses) != nil {
			return false
		}
		_, credential := values["observation_credential_use_sha256"]
		_, authentication := values["observation_authentication_context_sha256"]
		switch stringValue("observation_source") {
		case "MUTATION_RESPONSE":
			return len(requests) == 0 && len(responses) == 0 && !credential && !authentication
		case "READ_ONLY_RECONCILIATION":
			return len(requests) == 2 && len(responses) == 2 && credential && authentication
		default:
			return false
		}
	case "P-nested:WorkflowBackendIdentityV1-ROW-002":
		var digest string
		if context == nil || json.Unmarshal(values["composition_sha256"], &digest) != nil {
			return false
		}
		return context.digestValidForTarget("ArtifactBlobV1", digest)
	case "P-stage-secret-set-v1-ROW-001":
		var uses []map[string]json.RawMessage
		if json.Unmarshal(values["credential_uses"], &uses) != nil || len(uses) == 0 {
			return false
		}
		seen := make(map[string]struct{}, len(uses))
		for _, use := range uses {
			secretID := string(use["secret_id"])
			if secretID == "" {
				return false
			}
			if _, duplicate := seen[secretID]; duplicate {
				return false
			}
			seen[secretID] = struct{}{}
		}
		return true
	case "P-worker-capacity-reservation-v1-ROW-004":
		_, parent := values["parent_reservation_sha256"]
		_, revision := values["parent_envelope_revision"]
		return parent == revision
	default:
		return false
	}
}

func applyFrozenDerivationPositiveV1(predicate PredicateDescriptorV1, values map[string]json.RawMessage) error {
	setString := func(path, value string) { values[path] = mustMarshalCanonicalVectorStringV1(value) }
	stringValue := func(path string) string {
		var value string
		_ = json.Unmarshal(values[path], &value)
		return value
	}
	switch predicate.PredicateID {
	case "P-DIFF-001":
		rules := map[string]string{
			"B_IMPLEMENTATION":       "B_GRANT_BASE_TO_B_CANDIDATE",
			"C_BRANCH_ACCEPTANCE":    "C_GRANT_BASE_TO_UNCHANGED_C_CANDIDATE",
			"INTEGRATION_ACCEPTANCE": "INTEGRATION_BASE_TO_INTEGRATED_HEAD",
			"POST_MERGE_ACCEPTANCE":  "PREMERGE_BASE_TO_MERGE_RESULT",
		}
		rule := rules[stringValue("stage")]
		if rule == "" {
			return errors.New("P-DIFF-001 has an unknown stage")
		}
		setString("derivation_rule", rule)
	case "P-PR-002":
		_, number := values["pr_number"]
		_, node := values["pr_node_id"]
		if number != node {
			return errors.New("P-PR-002 has a partial PR identity")
		}
		if number {
			setString("mutation_mode", "UPDATE")
		} else {
			setString("mutation_mode", "CREATE")
		}
	case "P-MERGE-003":
		setString("observation_source", "MUTATION_RESPONSE")
		values["observation_read_request_sha256s"] = []byte("[]")
		values["observation_read_response_sha256s"] = []byte("[]")
		delete(values, "observation_credential_use_sha256")
		delete(values, "observation_authentication_context_sha256")
	case "P-nested:WorkflowBackendIdentityV1-ROW-002":
		// The composition is an ArtifactBlobV1 typed record installed by the
		// catalog context; its derivation is validated against that record.
	case "P-github-repository-observation-v1-ROW-001":
		setString("permission", "ADMIN")
	case "P-worker-capacity-reservation-v1-ROW-004":
		if _, parent := values["parent_reservation_sha256"]; parent {
			if _, revision := values["parent_envelope_revision"]; !revision {
				values["parent_envelope_revision"] = []byte("0")
			}
		} else {
			delete(values, "parent_envelope_revision")
		}
	case "P-effect-pre-call-closure-v1-ROW-001", "P-stage-secret-set-v1-ROW-001":
		// Typed-reference materialization and descriptor-valid set generation
		// already install the exact positive operands for these formulas.
	default:
		if _, ok := frozenCrossRecordPredicateIDsV1[predicate.PredicateID]; ok {
			return nil
		}
		return fmt.Errorf("derivation %s has no frozen formula", predicate.PredicateID)
	}
	return nil
}

func predicateHasFrozenFormulaV1(predicate PredicateDescriptorV1) bool {
	if predicate.Operator == PredicateDerivation || predicate.PredicateID == "P-RESOURCE-001" {
		return true
	}
	if _, ok := frozenCrossRecordPredicateIDsV1[predicate.PredicateID]; ok {
		return true
	}
	switch predicate.PredicateID {
	case "P-PUBLISHER-001", "P-PUBLISHER-002", "P-SUBJECT-001", "P-BARRIER-001", "P-EVENT-001", "P-BARRIER-008", "P-predecessor-writer-lease-v1-ROW-001", "P-RESOURCE-002":
		return true
	}
	return false
}

func frozenImplicationPredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, values map[string]json.RawMessage) (bool, bool) {
	stringValue := func(path string) string {
		var value string
		_ = json.Unmarshal(values[path], &value)
		return value
	}
	switch predicate.PredicateID {
	case "P-PUBLISHER-001":
		return stringValue("lifecycle") == "ACTIVE", true
	case "P-PUBLISHER-002":
		_, revision := values["terminal_revision"]
		operation := stringValue("terminal_operation")
		_, recovery := values["recovery_proof_sha256"]
		switch stringValue("lifecycle") {
		case "ACTIVE":
			return !revision && operation == "" && !recovery, true
		case "FINALIZED":
			return revision && operation == "FINALIZE" && !recovery, true
		case "ABANDONED":
			return revision && operation == "ABANDON" && recovery, true
		default:
			return false, true
		}
	case "P-SUBJECT-001":
		return bytes.Equal(values["candidate_oid"], values["diff_candidate_oid"]), true
	}
	return false, false
}

func frozenStatePredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, paths []string, values map[string]json.RawMessage) bool {
	stringValue := func(path string) string {
		var value string
		_ = json.Unmarshal(values[path], &value)
		return value
	}
	switch predicate.PredicateID {
	case "P-BARRIER-001":
		var digest string
		return json.Unmarshal(values["commitment_sha256"], &digest) == nil && digest == sha256Hex(values["commitment"])
	case "P-EVENT-001":
		kind := stringValue("effect_kind")
		from, to, source := stringValue("state_from"), stringValue("state_to"), stringValue("source")
		if kind == "PR" {
			return from == "INTEGRATION_ACCEPTED" && to == "READY_FOR_MERGE" && source == "assurance-pr-effect-v4"
		}
		return kind == "MERGE" && from == "READY_FOR_MERGE" && to == "MERGED" && source == "assurance-merge-effect-v4"
	case "P-BARRIER-008":
		kind := stringValue("effect_kind")
		from, to := stringValue("source_state"), stringValue("applied_state_to")
		if kind == "PR" {
			return from == "INTEGRATION_ACCEPTED" && to == "READY_FOR_MERGE"
		}
		return kind == "MERGE" && from == "READY_FOR_MERGE" && to == "MERGED"
	case "P-PUBLISHER-006":
		assembled, err1 := time.Parse(time.RFC3339Nano, stringValue("proof_assembled_at"))
		validFrom, err2 := time.Parse(time.RFC3339Nano, stringValue("valid_from"))
		expires, err3 := time.Parse(time.RFC3339Nano, stringValue("expires_at"))
		return err1 == nil && err2 == nil && err3 == nil && !validFrom.Before(assembled) && expires.After(validFrom) && !expires.After(assembled.Add(30*time.Second))
	case "P-predecessor-writer-lease-v1-ROW-001":
		return stringValue("lease_state") == "ACTIVE"
	case "P-RESOURCE-002":
		_, released := values["released_at_revision"]
		_, evidence := values["release_evidence_sha256"]
		if stringValue("lifecycle") == "RELEASED" {
			return released && evidence
		}
		return !released && !evidence
	}
	if len(paths) >= 2 {
		edges := frozenTransitionEdgesV1(predicate)
		if len(edges) != 0 {
			return edges[stringValue(paths[0])+"\x00"+stringValue(paths[1])]
		}
	}
	return false
}

func frozenDigestPreimagePredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, values, expected map[string]json.RawMessage) bool {
	if len(predicate.FieldPaths) == 0 {
		return false
	}
	if strings.HasSuffix(predicate.PredicateID, "-ROW-003") {
		if digest, handled := absenceProbeResultDigestV1(entry.SchemaID, values); handled {
			var actual string
			return json.Unmarshal(values["probe_result_sha256"], &actual) == nil && actual == digest
		}
	}
	if predicate.PredicateID == "P-effect-ledger-event-preimage-v1-ROW-003" {
		var eventID string
		expected, err := effectLedgerEventIDV1(values)
		return err == nil && json.Unmarshal(values["event_id"], &eventID) == nil && eventID == expected
	}
	path := predicate.FieldPaths[0]
	fieldIndex := -1
	for index, field := range entry.Fields {
		if field.FieldPath == path {
			fieldIndex = index
			break
		}
	}
	if !isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, fieldIndex) {
		fields := make(map[string]WireFieldDescriptorV1, len(entry.Fields))
		for _, field := range entry.Fields {
			fields[field.FieldPath] = field
		}
		paths := canonicalPredicateOperandPathsV1(entry, predicate, fields)
		output := ""
		for _, candidate := range paths {
			field := fields[candidate]
			if field.DigestTarget != "" || strings.HasSuffix(candidate, "_sha256") || candidate == "event_id" {
				output = candidate
				break
			}
		}
		changed := false
		compared := 0
		for _, candidate := range paths {
			field := fields[candidate]
			if candidate == output || field.JSONType == WireObject || field.JSONType == WireArray {
				continue
			}
			compared++
			actual, present := values[candidate]
			want, expectedPresent := expected[candidate]
			changed = changed || present != expectedPresent || present && !bytes.Equal(actual, want)
		}
		if compared == 0 {
			for _, field := range entry.Fields {
				if field.FieldPath == output || field.DigestTarget != "" || field.JSONType == WireObject || field.JSONType == WireArray {
					continue
				}
				actual, present := values[field.FieldPath]
				want, expectedPresent := expected[field.FieldPath]
				changed = changed || present != expectedPresent || present && !bytes.Equal(actual, want)
			}
		}
		if !changed {
			return true
		}
		if output == "" {
			return false
		}
		// Retaining the frozen output while an actual preimage operand changes
		// is the deterministic DIGEST_PREIMAGE rejection. Directly replacing
		// the output is left to its typed-reference/digest classifier.
		return !bytes.Equal(values[output], expected[output])
	}
	var actual string
	if json.Unmarshal(values[path], &actual) != nil {
		return false
	}
	preimage, err := marshalCanonicalVectorObjectV1(entry.Fields, values, path)
	if err == nil && actual == sha256Hex(preimage) {
		return true
	}
	// A predicate vector changes the preimage while deliberately retaining the
	// frozen positive digest. A direct digest mutation is classified by the
	// digest validator instead of being relabelled as a predicate failure.
	for _, field := range entry.Fields {
		if field.FieldPath == path || field.FieldPath == "event_id" || field.DigestTarget != "" || field.JSONType == WireObject || field.JSONType == WireArray {
			continue
		}
		value, present := values[field.FieldPath]
		want, expectedPresent := expected[field.FieldPath]
		if present != expectedPresent || present && !bytes.Equal(value, want) {
			return false
		}
	}
	return true
}

func absenceProbeResultDigestV1(schemaID string, values map[string]json.RawMessage) (string, bool) {
	if schemaID != "process-absence-observation-v1" && schemaID != "cgroup-absence-observation-v1" && schemaID != "container-absence-observation-v1" {
		return "", false
	}
	stringValue := func(path string) (string, bool) {
		var value string
		err := json.Unmarshal(values[path], &value)
		return value, err == nil
	}
	probeMethod, ok := stringValue("probe_method")
	if !ok {
		return "", true
	}
	var preimage bytes.Buffer
	preimage.WriteString(`{"probe_method":`)
	methodJSON, _ := json.Marshal(probeMethod)
	preimage.Write(methodJSON)
	switch schemaID {
	case "process-absence-observation-v1":
		path, pathOK := stringValue("proc_stat_path")
		expected, expectedOK := stringValue("expected_start_ticks")
		var disposition string
		_ = json.Unmarshal(values["process_disposition"], &disposition)
		if !pathOK || !expectedOK {
			return "", true
		}
		pathJSON, _ := json.Marshal(path)
		expectedJSON, _ := json.Marshal(expected)
		preimage.WriteString(`,"path":`)
		preimage.Write(pathJSON)
		preimage.WriteString(`,"expected_start_ticks":`)
		preimage.Write(expectedJSON)
		if observed, present := values["observed_start_ticks"]; present {
			preimage.WriteString(`,"observed_start_ticks":`)
			preimage.Write(observed)
		}
		resultJSON, _ := json.Marshal(disposition)
		preimage.WriteString(`,"result":`)
		preimage.Write(resultJSON)
	case "cgroup-absence-observation-v1":
		path, pathOK := stringValue("cgroup_path")
		if !pathOK {
			return "", true
		}
		pathJSON, _ := json.Marshal(path)
		preimage.WriteString(`,"path":`)
		preimage.Write(pathJSON)
		preimage.WriteString(`,"inode":`)
		preimage.Write(values["cgroup_inode"])
		preimage.WriteString(`,"populated":`)
		preimage.Write(values["populated"])
	case "container-absence-observation-v1":
		containerID, idOK := stringValue("container_id")
		disposition, dispositionOK := stringValue("container_disposition")
		if !idOK || !dispositionOK {
			return "", true
		}
		idJSON, _ := json.Marshal(containerID)
		resultJSON, _ := json.Marshal(disposition)
		preimage.WriteString(`,"container_id":`)
		preimage.Write(idJSON)
		preimage.WriteString(`,"http_status":404,"result":`)
		preimage.Write(resultJSON)
	default:
		return "", false
	}
	preimage.WriteByte('}')
	return sha256Hex(preimage.Bytes()), true
}

func effectLedgerEventIDV1(values map[string]json.RawMessage) (string, error) {
	var effectKind, stateTo string
	if json.Unmarshal(values["effect_kind"], &effectKind) != nil || json.Unmarshal(values["state_to"], &stateTo) != nil {
		return "", errors.New("event ID kind or destination is unresolved")
	}
	var payload map[string]json.RawMessage
	if json.Unmarshal(values["payload"], &payload) != nil {
		return "", errors.New("event ID payload is unresolved")
	}
	var intentDigest, winningOutcomeDigest string
	if json.Unmarshal(payload["intent_sha256"], &intentDigest) != nil || json.Unmarshal(payload["winning_outcome_sha256"], &winningOutcomeDigest) != nil {
		return "", errors.New("event ID payload digest chain is unresolved")
	}
	if effectKind == "" || stateTo == "" || validateExactLowerHex(intentDigest, 64) != nil || validateExactLowerHex(winningOutcomeDigest, 64) != nil {
		return "", errors.New("event ID tuple is invalid")
	}
	preimage := strings.Join([]string{"ABCP-V4-LEDGER-EVENT-ID-V1", effectKind, intentDigest, winningOutcomeDigest, stateTo}, "\x00")
	digest := sha256.Sum256([]byte(preimage))
	return hex.EncodeToString(digest[:16]), nil
}

func mutateCanonicalVectorV1(entry CanonicalVectorEntryV1, positive []byte, recipe CanonicalRejectionVectorV1, recordPositives map[string][]byte, context *canonicalPredicateContextV1) ([]byte, error) {
	if entry.RecordName == "ArtifactBlobV1" && entry.SchemaID == "artifact-blob-v1" {
		switch recipe.Mutation {
		case "BELOW_MIN":
			return []byte{}, nil
		case "ABOVE_MAX":
			return make([]byte, 33554433), nil
		default:
			return nil, fmt.Errorf("unsupported raw artifact mutation %s", recipe.Mutation)
		}
	}
	values, _, _, err := decodeCanonicalVectorObjectV1(positive)
	if err != nil {
		return nil, err
	}
	path, mutation := rejectionTargetAndMutationV1(entry.SchemaID, recipe.VectorID)
	if path == "$" {
		switch mutation {
		case "UNKNOWN_FIRST":
			return append([]byte(`{"__unknown":false,`), positive[1:]...), nil
		case "UNKNOWN_LAST":
			return append(append([]byte(nil), positive[:len(positive)-1]...), []byte(`,"__unknown":false}`)...), nil
		case "DUPLICATE_FIELD":
			if len(entry.Fields) == 0 {
				return nil, errors.New("record has no duplicable field")
			}
			field := entry.Fields[0]
			value, ok := values[field.FieldPath]
			if !ok {
				return nil, errors.New("first field is absent")
			}
			name, _ := json.Marshal(field.FieldPath)
			prefix := append(append(append([]byte{'{'}, name...), ':'), value...)
			prefix = append(prefix, ',')
			return append(prefix, positive[1:]...), nil
		case "INVALID_UTF8":
			result := append([]byte(nil), positive...)
			for index := 1; index < len(result)-1; index++ {
				if result[index] == 'a' {
					result[index] = 0xff
					return result, nil
				}
			}
			return append(result[:len(result)-1], []byte(",\"x\":\"\xff\"}")...), nil
		case "TRAILING_JSON":
			return append(append([]byte(nil), positive...), []byte("{}")...), nil
		}
	}
	if strings.HasPrefix(mutation, "PREDICATE_") {
		predicateID := strings.TrimPrefix(mutation, "PREDICATE_")
		predicate, found := canonicalVectorPredicateV1(entry.Predicates, predicateID)
		if !found {
			return nil, fmt.Errorf("unknown predicate %s", predicateID)
		}
		if err := mutatePredicateV1(entry, predicate, values, recordPositives, context); err != nil {
			return nil, fmt.Errorf("mutate %s paths=%v arguments=%v: %w", predicate.Operator, predicate.FieldPaths, predicate.Arguments, err)
		}
		changedPaths := append([]string(nil), predicate.FieldPaths...)
		if predicate.Operator == PredicateDigestPreimage {
			for index, field := range entry.Fields {
				if isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, index) {
					changedPaths = append(changedPaths, field.FieldPath)
				}
			}
		}
		return resealDependentDigestsV1(entry, values, changedPaths)
	}
	field, ok := canonicalVectorFieldV1(entry.Fields, path)
	if !ok {
		return nil, fmt.Errorf("unknown mutation path %s", path)
	}
	if _, present := values[path]; !present {
		values[path], err = descriptorPositiveForMutationV1(field, recordPositives)
		if err != nil {
			return nil, fmt.Errorf("materialize optional mutation target %s: %w", path, err)
		}
	}
	switch mutation {
	case "REMOVE":
		delete(values, path)
	case "NULL":
		values[path] = []byte("null")
	case "WRONG_TYPE":
		values[path] = wrongJSONTypeV1(field.JSONType)
	case "BELOW_MIN":
		values[path], err = belowMinimumJSONV1(field, recordPositives)
	case "ABOVE_MAX":
		values[path], err = aboveMaximumJSONV1(field, recordPositives)
	case "OVERSIZE":
		values[path], err = oversizedJSONV1(field)
	case "ENUM_INVALID":
		values[path], err = invalidEnumJSONV1(field)
	case "UPPERCASE":
		values[path], err = mutateStringJSONV1(values[path], uppercaseFirstAlphaV1)
	case "SHORT":
		values[path], err = mutateStringJSONV1(values[path], func(value string) string {
			if len(value) >= 2 {
				return value[:len(value)-2]
			}
			return ""
		})
	case "BAD_CHAR":
		values[path], err = badCharacterJSONV1(field)
	case "UNSORTED":
		values[path], err = unsortedArrayJSONV1(field, values[path], recordPositives)
	case "DUPLICATE_MEMBER":
		values[path], err = duplicateArrayMemberJSONV1(field, values[path], recordPositives)
	case "CONSTANT_CHANGED":
		var changed string
		changed, err = ConstantChangedV1(field)
		if err == nil {
			values[path], err = scalarForDescriptorV1(field, changed)
		}
	case "SELF_DIGEST_MISMATCH":
		values[path], err = mutateStringJSONV1(values[path], flipFirstHexV1)
	default:
		return nil, fmt.Errorf("unsupported canonical mutation %s", mutation)
	}
	if err != nil {
		return nil, err
	}
	if mutation != "SELF_DIGEST_MISMATCH" {
		return resealDependentDigestsV1(entry, values, []string{path})
	}
	return marshalCanonicalVectorObjectV1(entry.Fields, values, "")
}

func descriptorPositiveForMutationV1(field WireFieldDescriptorV1, recordPositives map[string][]byte) (json.RawMessage, error) {
	switch field.JSONType {
	case WireObject:
		if positive := recordPositives[field.RecordTarget]; len(positive) != 0 {
			return append(json.RawMessage(nil), positive...), nil
		}
	case WireArray:
		minimum := uint64(0)
		if field.MinItems != nil {
			minimum = *field.MinItems
		}
		return arrayOfSizeJSONV1(field, minimum, recordPositives)
	}
	return minimalDescriptorJSON(field)
}

func invalidEnumJSONV1(field WireFieldDescriptorV1) (json.RawMessage, error) {
	if field.JSONType != WireString || field.MinBytes == nil || field.MaxBytes == nil {
		return nil, errors.New("enum descriptor has no string bounds")
	}
	for length := *field.MinBytes; length <= *field.MaxBytes; length++ {
		for _, character := range []byte{'x', 'y', 'z'} {
			candidate := strings.Repeat(string(character), int(length))
			if ValidatePrimitiveWireValueV1(field.ValueType, candidate) != nil {
				return json.Marshal(candidate)
			}
		}
		if length == *field.MaxBytes {
			break
		}
	}
	return nil, errors.New("enum has no bounded invalid member")
}

func rejectionTargetAndMutationV1(schemaID, vectorID string) (string, string) {
	prefix := schemaID + "/"
	remaining := strings.TrimPrefix(vectorID, prefix)
	index := strings.LastIndexByte(remaining, '/')
	if index < 0 {
		return "$", remaining
	}
	path := remaining[:index]
	path = strings.ReplaceAll(path, "~1", "/")
	path = strings.ReplaceAll(path, "~0", "~")
	return path, remaining[index+1:]
}

func canonicalVectorFieldV1(fields []WireFieldDescriptorV1, path string) (WireFieldDescriptorV1, bool) {
	for _, field := range fields {
		if field.FieldPath == path {
			return field, true
		}
	}
	return WireFieldDescriptorV1{}, false
}

func canonicalVectorPredicateV1(predicates []PredicateDescriptorV1, id string) (PredicateDescriptorV1, bool) {
	for _, predicate := range predicates {
		if predicate.PredicateID == id {
			return predicate, true
		}
	}
	return PredicateDescriptorV1{}, false
}

func wrongJSONTypeV1(kind WireJSONType) json.RawMessage {
	if kind == WireBoolean {
		return []byte(`"wrong"`)
	}
	if kind == WireString {
		return []byte("false")
	}
	return []byte(`"wrong"`)
}

func belowMinimumJSONV1(field WireFieldDescriptorV1, recordPositives map[string][]byte) (json.RawMessage, error) {
	switch field.JSONType {
	case WireString:
		minimum := uint64(0)
		if field.MinBytes != nil {
			minimum = *field.MinBytes
		}
		if minimum == 0 {
			return nil, errors.New("string has no below-minimum value")
		}
		return json.Marshal(strings.Repeat("a", int(minimum-1)))
	case WireInteger:
		minimum := uint64(0)
		if field.MinU64 != nil {
			minimum = *field.MinU64
		}
		if minimum == 0 {
			return nil, errors.New("integer has no below-minimum value")
		}
		return []byte(strconv.FormatUint(minimum-1, 10)), nil
	case WireArray:
		minimum := uint64(0)
		if field.MinItems != nil {
			minimum = *field.MinItems
		}
		if minimum == 0 {
			return nil, errors.New("array has no below-minimum value")
		}
		return arrayOfSizeJSONV1(field, minimum-1, recordPositives)
	}
	return nil, errors.New("descriptor has no below-minimum mutation")
}

func aboveMaximumJSONV1(field WireFieldDescriptorV1, recordPositives map[string][]byte) (json.RawMessage, error) {
	switch field.JSONType {
	case WireInteger:
		if field.MaxU64 == nil || *field.MaxU64 == ^uint64(0) {
			return nil, errors.New("integer has no above-maximum value")
		}
		return []byte(strconv.FormatUint(*field.MaxU64+1, 10)), nil
	case WireArray:
		if field.MaxItems == nil {
			return nil, errors.New("array has no maximum")
		}
		return arrayOfSizeJSONV1(field, *field.MaxItems+1, recordPositives)
	}
	return nil, errors.New("descriptor has no above-maximum mutation")
}

func oversizedJSONV1(field WireFieldDescriptorV1) (json.RawMessage, error) {
	if field.MaxBytes == nil {
		return nil, errors.New("descriptor has no string maximum")
	}
	if field.JSONType == WireRawJSON {
		return []byte(`{"a":"` + strings.Repeat("a", int(*field.MaxBytes)) + `"}`), nil
	}
	if field.JSONType != WireString {
		return nil, errors.New("descriptor has no string maximum")
	}
	length := *field.MaxBytes + 1
	switch field.ValueType {
	case "ed25519PublicKeyHex", "ed25519SignatureHex", "ledgerEventID":
		length = *field.MaxBytes + 2
	case "v4LedgerEventID":
		// The frozen negative is the retained 32-byte/64-character form,
		// not an odd-length syntactic hex string.
		length = 64
	}
	return json.Marshal(strings.Repeat("a", int(length)))
}

func arrayOfSizeJSONV1(field WireFieldDescriptorV1, count uint64, positiveByRecord ...map[string][]byte) (json.RawMessage, error) {
	var recordPositives map[string][]byte
	if len(positiveByRecord) != 0 {
		recordPositives = positiveByRecord[0]
	}
	values := make([]json.RawMessage, 0, count)
	var literalElements []json.RawMessage
	if field.ValueType == "exact-literal-array" {
		if json.Unmarshal([]byte(field.LiteralValue), &literalElements) != nil || len(literalElements) == 0 {
			return nil, errors.New("exact literal array has no materializable element")
		}
	}
	for index := uint64(0); index < count; index++ {
		if len(literalElements) != 0 {
			values = append(values, append(json.RawMessage(nil), literalElements[index%uint64(len(literalElements))]...))
			continue
		}
		elementType := arrayElementTypeV1(field.ValueType)
		value := append(json.RawMessage(nil), recordPositives[elementType]...)
		var err error
		if len(value) == 0 {
			value, err = minimalArrayElementJSONV1(field, elementType, index)
		}
		if err != nil {
			return nil, err
		}
		values = append(values, value)
	}
	return json.Marshal(values)
}

func mutateStringJSONV1(raw json.RawMessage, mutate func(string) string) (json.RawMessage, error) {
	var value string
	if json.Unmarshal(raw, &value) != nil {
		return nil, errors.New("mutation target is not a string")
	}
	return json.Marshal(mutate(value))
}

func uppercaseFirstAlphaV1(value string) string {
	data := []byte(value)
	for index, character := range data {
		if character >= 'a' && character <= 'f' {
			data[index] = character - ('a' - 'A')
			break
		}
	}
	return string(data)
}

func flipFirstHexV1(value string) string {
	if value == "" {
		return value
	}
	if value[0] == 'a' {
		return "b" + value[1:]
	}
	return "a" + value[1:]
}

func badCharacterJSONV1(field WireFieldDescriptorV1) (json.RawMessage, error) {
	valueType := field.ValueType
	if field.JSONType == WireArray {
		valueType = arrayElementTypeV1(field.ValueType)
	}
	var invalid json.RawMessage
	switch valueType {
	case "path":
		invalid, _ = json.Marshal("/a")
	case "absPath":
		invalid, _ = json.Marshal("a")
	case "authorityDomain":
		invalid, _ = json.Marshal("a/b")
	default:
		if isHexWireType(valueType) {
			length := 64
			if field.MinBytes != nil {
				length = int(*field.MinBytes)
			}
			invalid, _ = json.Marshal("g" + strings.Repeat("a", length-1))
		}
	}
	if len(invalid) != 0 {
		if field.JSONType == WireArray {
			return json.Marshal([]json.RawMessage{invalid})
		}
		return invalid, nil
	}
	return nil, errors.New("descriptor has no BAD_CHAR mutation")
}

func unsortedArrayJSONV1(field WireFieldDescriptorV1, raw json.RawMessage, positiveByRecord ...map[string][]byte) (json.RawMessage, error) {
	var values []json.RawMessage
	if json.Unmarshal(raw, &values) != nil {
		return nil, errors.New("mutation target is not an array")
	}
	if len(values) < 2 {
		var err error
		valuesRaw, err := arrayOfSizeJSONV1(field, 2, positiveByRecord...)
		if err != nil {
			return nil, err
		}
		if json.Unmarshal(valuesRaw, &values) != nil {
			return nil, errors.New("cannot grow set for unsorted mutation")
		}
	}
	values[0], values[1] = values[1], values[0]
	return json.Marshal(values)
}

func duplicateArrayMemberJSONV1(field WireFieldDescriptorV1, raw json.RawMessage, positiveByRecord ...map[string][]byte) (json.RawMessage, error) {
	var values []json.RawMessage
	if json.Unmarshal(raw, &values) != nil {
		return nil, errors.New("mutation target is not an array")
	}
	if len(values) == 0 {
		valuesRaw, err := arrayOfSizeJSONV1(field, 1, positiveByRecord...)
		if err != nil {
			return nil, err
		}
		if json.Unmarshal(valuesRaw, &values) != nil {
			return nil, errors.New("cannot populate set for duplicate-member mutation")
		}
	}
	values = append(values, append(json.RawMessage(nil), values[0]...))
	sort.Slice(values, func(i, j int) bool { return bytes.Compare(values[i], values[j]) < 0 })
	return json.Marshal(values)
}

func scalarForDescriptorV1(field WireFieldDescriptorV1, value string) (json.RawMessage, error) {
	switch field.JSONType {
	case WireBoolean, WireInteger, WireArray:
		return []byte(value), nil
	default:
		return json.Marshal(value)
	}
}

func mutatePredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, values map[string]json.RawMessage, recordPositives map[string][]byte, context *canonicalPredicateContextV1) error {
	fields := make(map[string]WireFieldDescriptorV1, len(entry.Fields))
	for _, field := range entry.Fields {
		fields[field.FieldPath] = field
	}
	paths, operandErr := resolveCanonicalPredicateOperandPathsV1(entry, predicate, fields)
	if operandErr != nil && !predicateHasFrozenFormulaV1(predicate) {
		return operandErr
	}
	if predicate.PredicateID == "P-EVENT-001" && entry.RecordName != "EffectLedgerEventPreimageV1" {
		changed, err := primitiveValidChangeV1(fields["event_id"], values["event_id"])
		if err != nil {
			return err
		}
		values["event_id"] = changed
		return nil
	}
	if _, compatible := frozenCrossRecordPredicateIDsV1[predicate.PredicateID]; compatible {
		path := frozenCrossRecordMutationPathV1(entry, predicate, paths, fields)
		if path == "" {
			if operandErr != nil {
				return operandErr
			}
			return fmt.Errorf("predicate %s has no closed frozen mutation rule", predicate.PredicateID)
		}
		changed, err := primitiveValidChangeV1(fields[path], values[path])
		if err != nil {
			return err
		}
		values[path] = changed
		return nil
	}
	switch predicate.Operator {
	case PredicateExactLiteral:
		field := fields[paths[0]]
		changed, err := ConstantChangedV1(field)
		if err != nil {
			return err
		}
		values[paths[0]], err = scalarForDescriptorV1(field, changed)
		return err
	case PredicateAllEqual:
		if len(paths) < 2 {
			return errors.New("ALL_EQUAL requires two named operands")
		}
		for _, path := range paths {
			field := fields[path]
			if field.LiteralValue != "" {
				continue
			}
			changed, err := primitiveValidChangeV1(field, values[path])
			if err != nil {
				return err
			}
			values[path] = changed
			return nil
		}
		return errors.New("ALL_EQUAL has no non-literal participant")
	case PredicateExactlyOne:
		for _, path := range paths {
			if _, present := values[path]; !present {
				value, err := minimalDescriptorJSON(fields[path])
				if err != nil {
					return err
				}
				values[path] = value
				return nil
			}
		}
		delete(values, paths[len(paths)-1])
	case PredicateOrdinalSuccess:
		integerPaths := integerPredicatePathsV1(paths, fields)
		if len(integerPaths) == 0 {
			return errors.New("ORDINAL_SUCCESSOR requires an integer operand")
		}
		if len(integerPaths) == 1 {
			var value uint64
			if json.Unmarshal(values[integerPaths[0]], &value) != nil {
				return errors.New("ordinal operand is invalid")
			}
			values[integerPaths[0]] = []byte(strconv.FormatUint(value+1, 10))
			break
		}
		var successor uint64
		if json.Unmarshal(values[integerPaths[1]], &successor) != nil || successor == ^uint64(0) {
			return errors.New("ordinal successor is invalid")
		}
		values[integerPaths[1]] = []byte(strconv.FormatUint(successor+1, 10))
	case PredicateSubset:
		arrayPaths := make([]string, 0, len(paths))
		for _, path := range paths {
			if fields[path].JSONType == WireArray {
				arrayPaths = append(arrayPaths, path)
			}
		}
		if len(arrayPaths) < 2 {
			return errors.New("SUBSET requires two named array operands")
		}
		field := fields[arrayPaths[0]]
		var subset, superset []json.RawMessage
		if json.Unmarshal(values[arrayPaths[0]], &subset) != nil || len(arrayPaths) < 2 || json.Unmarshal(values[arrayPaths[1]], &superset) != nil {
			return errors.New("SUBSET operands are invalid")
		}
		members := make(map[string]struct{}, len(superset))
		for _, member := range superset {
			members[string(member)] = struct{}{}
		}
		var candidate json.RawMessage
		for ordinal := uint64(0); ordinal < 256; ordinal++ {
			next, err := minimalArrayElementJSONV1(field, arrayElementTypeV1(field.ValueType), ordinal)
			if err != nil {
				return err
			}
			if _, exists := members[string(next)]; !exists {
				candidate = next
				break
			}
		}
		if len(candidate) == 0 {
			return errors.New("SUBSET has no primitive-minimal foreign member")
		}
		subset = append(subset, candidate)
		if strings.Contains(field.ValueType, "(set") {
			sort.Slice(subset, func(i, j int) bool { return bytes.Compare(subset[i], subset[j]) < 0 })
		}
		values[arrayPaths[0]], _ = json.Marshal(subset)
	case PredicateDigestPreimage:
		if _, handled := absenceProbeResultDigestV1(entry.SchemaID, values); handled && containsCanonicalVectorStringV1(predicate.FieldPaths, "probe_result_sha256") {
			path := map[string]string{
				"process-absence-observation-v1":   "proc_stat_path",
				"cgroup-absence-observation-v1":    "cgroup_path",
				"container-absence-observation-v1": "container_id",
			}[entry.SchemaID]
			changed, err := primitiveValidChangeV1(fields[path], values[path])
			if err != nil {
				return err
			}
			values[path] = changed
			return nil
		}
		if predicate.PredicateID == "P-effect-ledger-event-preimage-v1-ROW-003" {
			payload, order, duplicate, err := decodeCanonicalVectorObjectV1(values["payload"])
			if err != nil || duplicate {
				return errors.New("event ID payload is invalid")
			}
			var intent string
			if json.Unmarshal(payload["intent_sha256"], &intent) != nil {
				return errors.New("event ID intent digest is invalid")
			}
			payload["intent_sha256"] = mustMarshalCanonicalVectorStringV1(flipFirstHexV1(intent))
			values["payload"] = marshalCanonicalRawObjectV1(order, payload)
			return nil
		}
		outputs := make(map[string]struct{})
		candidates := append([]string(nil), paths...)
		selfDigest := false
		for _, path := range paths {
			field := fields[path]
			if field.DigestTarget != "" || strings.HasSuffix(path, "_sha256") || path == "event_id" {
				outputs[path] = struct{}{}
			}
		}
		for output := range outputs {
			fieldIndex := -1
			for index, field := range entry.Fields {
				if field.FieldPath == output {
					fieldIndex = index
					break
				}
			}
			if isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, fieldIndex) {
				selfDigest = true
				candidates = candidates[:0]
				for _, field := range entry.Fields[:fieldIndex] {
					candidates = append(candidates, field.FieldPath)
				}
				candidates = append(candidates, output)
				break
			}
		}
		for _, path := range candidates {
			field := fields[path]
			if _, output := outputs[path]; output || field.LiteralValue != "" || field.DigestTarget != "" || selfDigest && (field.JSONType == WireObject || field.JSONType == WireArray) {
				continue
			}
			raw, present := values[path]
			if !present {
				continue
			}
			changed, err := primitiveValidChangeV1(field, raw)
			if err == nil {
				values[path] = changed
				return nil
			}
		}
		if selfDigest {
			for _, path := range candidates {
				field := fields[path]
				if _, output := outputs[path]; output || field.DigestTarget != "" || field.LiteralValue == "" {
					continue
				}
				changed, err := primitiveValidChangeV1(field, values[path])
				if err == nil {
					values[path] = changed
					return nil
				}
			}
		}
		return errors.New("digest preimage has no primitive-valid mutable operand")
	case PredicateTypedReference:
		for _, path := range paths {
			field := fields[path]
			raw, present := values[path]
			if !present {
				var err error
				raw, err = descriptorPositiveForMutationV1(field, nil)
				if err != nil {
					continue
				}
				values[path] = raw
			}
			if field.DigestTarget == "" || context == nil {
				continue
			}
			foreignDigest, ok := context.firstForeignDigest(field.DigestTarget)
			if !ok {
				continue
			}
			foreign := mustMarshalCanonicalVectorStringV1(foreignDigest)
			if field.JSONType == WireArray {
				var elements []json.RawMessage
				if json.Unmarshal(raw, &elements) != nil {
					continue
				}
				if len(elements) == 0 {
					populated, err := arrayOfSizeJSONV1(field, 1)
					if err != nil || json.Unmarshal(populated, &elements) != nil {
						continue
					}
				}
				elements[0] = foreign
				values[path], _ = json.Marshal(elements)
				return nil
			}
			values[path] = foreign
			return nil
		}
		return errors.New("typed reference has no descriptor-valid substitution")
	case PredicateDerivation:
		return mutateFrozenDerivationPredicateV1(entry, predicate, fields, values, context)
	case PredicateStateTransition:
		return mutateFrozenStatePredicateV1(entry, predicate, paths, fields, values)
	case PredicateIfAndOnlyIf, PredicateImplies:
		return mutateFrozenImplicationPredicateV1(entry, predicate, paths, fields, values)
	case PredicateAggregateLEQ:
		if predicate.PredicateID == "P-RESOURCE-001" {
			expected, err := materializedResourceProfileValuesV1(values, context)
			if err != nil {
				return err
			}
			path := resourceSummedFieldsV1[0]
			var sum uint64
			if json.Unmarshal(expected[path], &sum) != nil {
				return errors.New("P-RESOURCE-001 aggregate output is invalid")
			}
			field := fields[path]
			if field.MaxU64 != nil && sum == *field.MaxU64 {
				if sum == 0 {
					return errors.New("P-RESOURCE-001 has no descriptor-valid aggregate violation")
				}
				values[path] = []byte(strconv.FormatUint(sum-1, 10))
				return nil
			}
			values[path] = []byte(strconv.FormatUint(sum+1, 10))
			return nil
		}
		integerPaths := integerPredicatePathsV1(paths, fields)
		if len(integerPaths) != len(paths) || len(integerPaths) < 2 {
			return errors.New("aggregate requires addend and limit")
		}
		var sum uint64
		for _, path := range integerPaths[:len(integerPaths)-1] {
			var addend uint64
			if json.Unmarshal(values[path], &addend) != nil || ^uint64(0)-sum < addend {
				return errors.New("aggregate addend is invalid")
			}
			sum += addend
		}
		var limit uint64
		if json.Unmarshal(values[integerPaths[len(integerPaths)-1]], &limit) != nil {
			return errors.New("aggregate limit is invalid")
		}
		if sum > limit || limit == ^uint64(0) {
			return errors.New("aggregate positive is not within its limit")
		}
		var lowest uint64
		if json.Unmarshal(values[integerPaths[0]], &lowest) != nil || ^uint64(0)-lowest < limit-sum+1 {
			return errors.New("aggregate mutation overflows")
		}
		values[integerPaths[0]] = []byte(strconv.FormatUint(lowest+(limit-sum+1), 10))
	default:
		return errors.New("predicate operator is not executable")
	}
	return nil
}

func frozenCrossRecordMutationPathV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, paths []string, fields map[string]WireFieldDescriptorV1) string {
	candidates := map[string][]string{
		"P-PUBLISHER-003": {"opened_revision"}, "P-PUBLISHER-004": {"committed_stage_revision"},
		"P-PUBLISHER-005": {"finalized_revision"}, "P-PUBLISHER-007": {"abandoned_revision"},
		"P-RESOURCE-003": {"direct_materialized_resource_profile_id", "materialized_resource_profile_id"},
		"P-DIFF-002":     {"base_oid"}, "P-DIFF-003": {"base_oid"}, "P-DIFF-004": {"diff_base_oid"}, "P-DIFF-005": {"match_count"},
		"P-BARRIER-002": {"expected_pg_revision"}, "P-BARRIER-003": {"allowed_state_to"},
		"P-BARRIER-004": {"pg_revision"}, "P-BARRIER-005": {"locked_pg_revision"},
		"P-BARRIER-007": {"resolved_at_pg_revision"}, "P-RECONCILE-001": {"derived_at_pg_revision"},
		"P-RECONCILE-002": {"reconciliation_ordinal"}, "P-MERGE-000": {"invocation_id", "write_id"},
		"P-MERGE-001": {"base_ref"}, "P-MERGE-002": {"request_identity"},
		"P-READY-001": {"run_id", "repository_identity"}, "P-PR-001": {"base_ref"},
		"P-PR-003": {"observation_source"}, "P-EFFECT-001": {"principal_type"},
		"P-EFFECT-002": {"method"}, "P-PUBLISHER-006": {"proved_at_revision", "proof_assembled_at"},
		"P-PARENT-001": {"sequence"}, "P-SUBJECT-002": {"stage_generation"},
		"P-effect-attempt-index-v1-ROW-001": {"effect_ordinal"}, "P-effect-attempt-index-v1-ROW-002": {"effect_ordinal"},
		"P-effect-reauthorization-v1-ROW-001": {"new_effect_ordinal"}, "P-phase-authority-v4-ROW-001": {"stage"},
		"P-process-absence-observation-v1-ROW-001": {"expected_pid"}, "P-process-absence-observation-v1-ROW-002": {"expected_start_ticks"},
		"P-provider-read-response-v1-ROW-001": {"parser"}, "P-provider-read-response-v1-ROW-009": {"parser"},
		"P-secret-scan-evidence-v2-ROW-001": {"match_count"}, "P-stage-subject-v1-ROW-002": {"stage"},
		"P-worker-observation-key-v1-ROW-002": {"observer_identity"}, "P-github-git-ref-observation-v1-ROW-001": {"ref"},
		"P-container-absence-observation-v1-ROW-002": {"container_id"}, "P-pr-effect-request-v1-ROW-004": {"body"},
		"P-github-installation-repositories-page-v1-ROW-001": {"has_next"}, "P-merge-provider-observation-v1-ROW-002": {"base_before_oid"},
		"P-governance-controller-state-v2-ROW-002": {"revision"},
		"P-pr-effect-reconciliation-v1-ROW-003":    {"disposition"}, "P-merge-effect-reconciliation-v1-ROW-003": {"disposition"},
		"P-pr-provider-observation-v1-ROW-004":         {"authenticated"},
		"P-provider-authentication-context-v1-ROW-002": {"valid_through"},
		"P-ledger-evidence-ref-list-v1-ROW-001":        {"kind"},
		"P-ledger-evidence-ref-list-v1-ROW-002":        {"kind"},
		"P-pr-publication-authority-v1-ROW-001":        {"repository_identity"},
		"P-stage-diff-lineage-v1-ROW-003":              {"base_oid"},
		"P-phase-checkpoint-v2-ROW-002":                {"kind"},
	}
	for _, path := range candidates[predicate.PredicateID] {
		if field, ok := fields[path]; ok && field.JSONType != WireObject && field.JSONType != WireRawJSON {
			return path
		}
	}
	return ""
}

func mutateFrozenDerivationPredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, fields map[string]WireFieldDescriptorV1, values map[string]json.RawMessage, context *canonicalPredicateContextV1) error {
	switch predicate.PredicateID {
	case "P-DIFF-001":
		field := fields["derivation_rule"]
		changed, err := primitiveValidChangeV1(field, values["derivation_rule"])
		if err != nil {
			return err
		}
		values["derivation_rule"] = changed
	case "P-github-repository-observation-v1-ROW-001":
		values["permission"] = mustMarshalCanonicalVectorStringV1("READ")
	case "P-effect-pre-call-closure-v1-ROW-001":
		if context == nil {
			return errors.New("effect union derivation has no catalog context")
		}
		var kind string
		_ = json.Unmarshal(values["effect_kind"], &kind)
		foreignType := "PREffectIntentV1"
		if kind == "PR" {
			foreignType = "MergeEffectIntentV1"
		}
		positive := context.recordPositiveByType[foreignType]
		if len(positive) == 0 {
			return errors.New("effect union derivation has no opposite-arm record")
		}
		values["intent_sha256"] = mustMarshalCanonicalVectorStringV1(sha256Hex(positive))
	case "P-PR-002":
		if string(values["mutation_mode"]) == `"CREATE"` {
			values["mutation_mode"] = mustMarshalCanonicalVectorStringV1("UPDATE")
		} else {
			values["mutation_mode"] = mustMarshalCanonicalVectorStringV1("CREATE")
		}
	case "P-MERGE-003":
		values["observation_source"] = mustMarshalCanonicalVectorStringV1("READ_ONLY_RECONCILIATION")
	case "P-nested:WorkflowBackendIdentityV1-ROW-002":
		var digest string
		if json.Unmarshal(values["composition_sha256"], &digest) != nil {
			return errors.New("workflow backend composition digest is invalid")
		}
		values["composition_sha256"] = mustMarshalCanonicalVectorStringV1(flipFirstHexV1(digest))
	case "P-stage-secret-set-v1-ROW-001":
		var uses []json.RawMessage
		if json.Unmarshal(values["credential_uses"], &uses) != nil || len(uses) == 0 {
			return errors.New("stage secret derivation has no credential use")
		}
		var duplicate map[string]json.RawMessage
		if json.Unmarshal(uses[0], &duplicate) != nil {
			return errors.New("stage secret credential use is invalid")
		}
		duplicate["byte_length"] = []byte("1")
		order := []string{"secret_id", "secret_capability", "acquisition_identity_sha256", "value_commitment_sha256", "byte_length"}
		second := marshalCanonicalRawObjectV1(order, duplicate)
		uses = append(uses, second)
		sort.Slice(uses, func(i, j int) bool { return bytes.Compare(uses[i], uses[j]) < 0 })
		values["credential_uses"], _ = json.Marshal(uses)
	case "P-worker-capacity-reservation-v1-ROW-004":
		if _, parent := values["parent_reservation_sha256"]; parent {
			delete(values, "parent_envelope_revision")
		} else {
			value, err := minimalDescriptorJSON(fields["parent_envelope_revision"])
			if err != nil {
				return err
			}
			values["parent_envelope_revision"] = value
		}
	default:
		return fmt.Errorf("derivation %s has no frozen mutation", predicate.PredicateID)
	}
	return nil
}

func mustMarshalCanonicalVectorStringV1(value string) json.RawMessage {
	encoded, _ := json.Marshal(value)
	return encoded
}

func mutateFrozenImplicationPredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, paths []string, fields map[string]WireFieldDescriptorV1, values map[string]json.RawMessage) error {
	setString := func(path, value string) { values[path] = mustMarshalCanonicalVectorStringV1(value) }
	switch predicate.PredicateID {
	case "P-PUBLISHER-001":
		setString("lifecycle", "ABANDONED")
		return nil
	case "P-PUBLISHER-002":
		setString("lifecycle", "ABANDONED")
		delete(values, "terminal_revision")
		delete(values, "terminal_operation")
		delete(values, "recovery_proof_sha256")
		return nil
	case "P-SUBJECT-001":
		values["diff_candidate_oid"] = mustMarshalCanonicalVectorStringV1(strings.Repeat("b", 40))
		return nil
	}
	if len(paths) < 2 {
		return errors.New("implication requires antecedent and consequent")
	}
	antecedent := paths[0]
	consequent := paths[1]
	antecedentField := fields[antecedent]
	consequentField := fields[consequent]
	if antecedentField.JSONType == WireBoolean {
		values[antecedent] = []byte("true")
	} else if antecedentField.Optional {
		value, err := descriptorPositiveForMutationV1(antecedentField, nil)
		if err != nil {
			return err
		}
		values[antecedent] = value
	} else {
		return errors.New("implication antecedent has no exact truth semantics")
	}
	if consequentField.JSONType == WireBoolean {
		values[consequent] = []byte("false")
	} else if consequentField.Optional {
		delete(values, consequent)
	} else {
		return errors.New("implication consequent has no exact false semantics")
	}
	return nil
}

func mutateFrozenStatePredicateV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, paths []string, fields map[string]WireFieldDescriptorV1, values map[string]json.RawMessage) error {
	setString := func(path, value string) { values[path] = mustMarshalCanonicalVectorStringV1(value) }
	switch predicate.PredicateID {
	case "P-BARRIER-001":
		changed, err := primitiveValidChangeV1(fields["commitment"], values["commitment"])
		if err != nil {
			return err
		}
		values["commitment"] = changed
		return nil
	case "P-EVENT-001":
		var source string
		_ = json.Unmarshal(values["state_from"], &source)
		allowed := map[string]bool{}
		var effectKind string
		_ = json.Unmarshal(values["effect_kind"], &effectKind)
		if effectKind == "PR" {
			allowed[source+"\x00READY_FOR_MERGE"] = true
		} else {
			allowed[source+"\x00MERGED"] = true
		}
		destination, err := firstDisallowedClosedStateV1(source, frozenEnumValues["coordination_state"], allowed)
		if err != nil {
			return err
		}
		setString("state_to", destination)
		return nil
	case "P-BARRIER-008":
		var source string
		_ = json.Unmarshal(values["source_state"], &source)
		allowed := map[string]bool{}
		var effectKind string
		_ = json.Unmarshal(values["effect_kind"], &effectKind)
		if effectKind == "PR" {
			allowed[source+"\x00READY_FOR_MERGE"] = true
		} else {
			allowed[source+"\x00MERGED"] = true
		}
		destination, err := firstDisallowedClosedStateV1(source, frozenEnumValues["coordination_state"], allowed)
		if err != nil {
			return err
		}
		setString("applied_state_to", destination)
		return nil
	case "P-PUBLISHER-006":
		values["expires_at"] = append(json.RawMessage(nil), values["valid_from"]...)
		return nil
	case "P-predecessor-writer-lease-v1-ROW-001":
		setString("lease_state", "RELEASED")
		return nil
	case "P-RESOURCE-002":
		setString("lifecycle", "RELEASED")
		delete(values, "released_at_revision")
		delete(values, "release_evidence_sha256")
		return nil
	}
	if len(paths) >= 2 {
		edges := frozenTransitionEdgesV1(predicate)
		if len(edges) != 0 {
			var source string
			if json.Unmarshal(values[paths[0]], &source) != nil {
				return errors.New("state transition source is invalid")
			}
			members := canonicalClosedEnumMembersV1(fields[paths[1]])
			destination, err := firstDisallowedClosedStateV1(source, members, edges)
			if err != nil {
				return err
			}
			setString(paths[1], destination)
			return nil
		}
	}
	path := canonicalStateDestinationPathV1(entry, predicate, paths)
	if path == "" {
		return errors.New("state transition has no destination")
	}
	field := fields[path]
	if _, present := values[path]; !present {
		value, err := descriptorPositiveForMutationV1(field, nil)
		if err != nil {
			return err
		}
		values[path] = value
	}
	changed, err := primitiveValidChangeV1(field, values[path])
	if err != nil {
		return err
	}
	values[path] = changed
	return nil
}

func firstDisallowedClosedStateV1(source string, members []string, allowed map[string]bool) (string, error) {
	members = append([]string(nil), members...)
	sort.Strings(members)
	for _, destination := range members {
		if !allowed[source+"\x00"+destination] {
			return destination, nil
		}
	}
	return "", errors.New("state transition has no closed-enum invalid destination")
}

var frozenTransitionEdgePatternV1 = regexp.MustCompile(`([A-Z][A-Z0-9_]*)\s*(?:→|->)\s*([A-Z][A-Z0-9_]*)`)

func frozenTransitionEdgesV1(predicate PredicateDescriptorV1) map[string]bool {
	edges := make(map[string]bool)
	for _, argument := range predicate.Arguments {
		for _, match := range frozenTransitionEdgePatternV1.FindAllStringSubmatch(argument, -1) {
			edges[match[1]+"\x00"+match[2]] = true
		}
	}
	return edges
}

func canonicalClosedEnumMembersV1(field WireFieldDescriptorV1) []string {
	if members, ok := frozenEnumValues[field.ValueType]; ok {
		return append([]string(nil), members...)
	}
	if strings.HasPrefix(field.ValueType, "{") && strings.HasSuffix(field.ValueType, "}") {
		parts := strings.Split(strings.Trim(field.ValueType, "{}"), ",")
		result := make([]string, 0, len(parts))
		for _, part := range parts {
			if member := strings.TrimSpace(part); member != "" {
				result = append(result, member)
			}
		}
		sort.Strings(result)
		return result
	}
	return nil
}

func containsCanonicalVectorStringV1(values []string, target string) bool {
	for _, value := range values {
		if value == target {
			return true
		}
	}
	return false
}

func canonicalPredicateOperandPathsV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, fields map[string]WireFieldDescriptorV1) []string {
	paths, _ := resolveCanonicalPredicateOperandPathsV1(entry, predicate, fields)
	return paths
}

func resolveCanonicalPredicateOperandPathsV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, fields map[string]WireFieldDescriptorV1) ([]string, error) {
	result := make([]string, 0, len(predicate.FieldPaths))
	recordWide := false
	appendPath := func(path string) {
		if path == "" || containsCanonicalVectorStringV1(result, path) {
			return
		}
		if _, exists := fields[path]; exists {
			result = append(result, path)
		}
	}
	for _, path := range predicate.FieldPaths {
		if path == "$" {
			recordWide = true
			continue
		}
		if _, exists := fields[path]; !exists {
			return nil, fmt.Errorf("predicate %s names unknown operand %s", predicate.PredicateID, path)
		}
		appendPath(path)
	}
	arguments := strings.Join(predicate.Arguments, " ")
	for _, field := range entry.Fields {
		if containsFieldToken(arguments, field.FieldPath) {
			appendPath(field.FieldPath)
		}
	}
	if recordWide && len(result) == 0 {
		return nil, fmt.Errorf("record-wide predicate %s does not name operands in normalized arguments", predicate.PredicateID)
	}
	minimum := predicateOperandCountV1(predicate.Operator)
	if len(result) < minimum {
		return result, fmt.Errorf("predicate %s resolves %d operands, requires %d", predicate.PredicateID, len(result), minimum)
	}
	return result, nil
}

func canonicalStateDestinationPathV1(entry CanonicalVectorEntryV1, predicate PredicateDescriptorV1, paths []string) string {
	for index := len(paths) - 1; index >= 0; index-- {
		field, ok := canonicalVectorFieldV1(entry.Fields, paths[index])
		if ok && (isClosedEnumType(field.ValueType) || strings.HasPrefix(field.ValueType, "{")) {
			return paths[index]
		}
	}
	if len(paths) != 0 {
		return paths[len(paths)-1]
	}
	return ""
}

func predicateOperandCountV1(operator PredicateOperator) int {
	switch operator {
	case PredicateAllEqual, PredicateIfAndOnlyIf, PredicateImplies, PredicateSubset, PredicateOrdinalSuccess, PredicateStateTransition, PredicateAggregateLEQ, PredicateExactlyOne:
		return 2
	default:
		return 1
	}
}

func primitiveValidChangeV1(field WireFieldDescriptorV1, raw json.RawMessage) (json.RawMessage, error) {
	switch field.JSONType {
	case WireArray:
		var values []json.RawMessage
		if json.Unmarshal(raw, &values) != nil {
			return nil, errors.New("array operand is invalid")
		}
		if len(values) == 0 {
			if field.MaxItems != nil && *field.MaxItems == 0 {
				return nil, errors.New("array operand cannot change cardinality")
			}
			value, err := minimalArrayElementJSONV1(field, arrayElementTypeV1(field.ValueType), 0)
			if err != nil {
				return nil, err
			}
			return json.Marshal([]json.RawMessage{value})
		}
		elementType := arrayElementTypeV1(field.ValueType)
		element, err := ResolveWireFieldDescriptorV1(field.SchemaID, field.FieldPath, field.Ordinal, elementType, false)
		if err != nil {
			return nil, err
		}
		changed, err := primitiveValidChangeV1(element, values[0])
		if err != nil {
			return nil, err
		}
		values[0] = changed
		if strings.Contains(field.ValueType, "(set") {
			sort.Slice(values, func(i, j int) bool { return bytes.Compare(values[i], values[j]) < 0 })
		}
		return json.Marshal(values)
	case WireObject:
		values, order, duplicate, err := decodeCanonicalVectorObjectV1(raw)
		if err != nil || duplicate {
			return nil, errors.New("object operand is invalid")
		}
		for _, name := range order {
			var value uint64
			if json.Unmarshal(values[name], &value) == nil && value < uint64(^uint64(0)) {
				values[name] = []byte(strconv.FormatUint(value+1, 10))
				return marshalCanonicalRawObjectV1(order, values), nil
			}
		}
		for _, name := range order {
			var value bool
			if string(values[name]) != "true" && string(values[name]) != "false" {
				continue
			}
			if json.Unmarshal(values[name], &value) == nil {
				values[name] = []byte(strconv.FormatBool(!value))
				return marshalCanonicalRawObjectV1(order, values), nil
			}
		}
		for _, name := range order {
			var value string
			if json.Unmarshal(values[name], &value) == nil && value != "" {
				replacement := byte('a')
				if value[len(value)-1] == replacement {
					replacement = 'b'
				}
				values[name], _ = json.Marshal(value[:len(value)-1] + string(replacement))
				return marshalCanonicalRawObjectV1(order, values), nil
			}
		}
	case WireString:
		var value string
		if json.Unmarshal(raw, &value) != nil {
			return nil, errors.New("string operand is invalid")
		}
		if field.ValueType == "procStart" {
			number, err := strconv.ParseUint(value, 10, 64)
			if err == nil && number != ^uint64(0) {
				return json.Marshal(strconv.FormatUint(number+1, 10))
			}
		}
		if members, ok := frozenEnumValues[field.ValueType]; ok {
			for _, member := range members {
				if member != value {
					return json.Marshal(member)
				}
			}
		}
		if strings.HasPrefix(field.ValueType, "{") && strings.HasSuffix(field.ValueType, "}") {
			for _, member := range strings.Split(strings.Trim(field.ValueType, "{}"), ",") {
				member = strings.TrimSpace(member)
				if member != "" && member != value {
					return json.Marshal(member)
				}
			}
		}
		if isHexWireType(field.ValueType) {
			return json.Marshal(flipFirstHexV1(value))
		}
		for index := len(value) - 1; index >= 0; index-- {
			for _, replacement := range []byte{'a', 'b', '0', '1', '-', '_'} {
				if value[index] == replacement {
					continue
				}
				candidate := value[:index] + string(replacement) + value[index+1:]
				if ValidatePrimitiveWireValueV1(field.ValueType, candidate) == nil {
					return json.Marshal(candidate)
				}
			}
		}
	case WireInteger:
		var value uint64
		if json.Unmarshal(raw, &value) == nil && (field.MaxU64 == nil || value < *field.MaxU64) {
			return []byte(strconv.FormatUint(value+1, 10)), nil
		}
	case WireBoolean:
		var value bool
		if json.Unmarshal(raw, &value) == nil {
			return []byte(strconv.FormatBool(!value)), nil
		}
	}
	return nil, errors.New("operand has no primitive-valid change")
}

func marshalCanonicalRawObjectV1(order []string, values map[string]json.RawMessage) []byte {
	var result bytes.Buffer
	result.WriteByte('{')
	for index, name := range order {
		if index != 0 {
			result.WriteByte(',')
		}
		encodedName, _ := json.Marshal(name)
		result.Write(encodedName)
		result.WriteByte(':')
		result.Write(values[name])
	}
	result.WriteByte('}')
	return result.Bytes()
}

func resealDependentDigestsV1(entry CanonicalVectorEntryV1, values map[string]json.RawMessage, changed []string) ([]byte, error) {
	changedSet := make(map[string]struct{}, len(changed))
	for _, path := range changed {
		changedSet[path] = struct{}{}
	}
	for fieldIndex, field := range entry.Fields {
		if !isSelfDigestFieldIndexV1(entry.RecordName, entry.SchemaID, entry.Fields, fieldIndex) {
			continue
		}
		if _, directlyChanged := changedSet[field.FieldPath]; directlyChanged {
			continue
		}
		preimage, err := marshalCanonicalVectorObjectV1(entry.Fields, values, field.FieldPath)
		if err != nil {
			return nil, err
		}
		values[field.FieldPath], _ = json.Marshal(sha256Hex(preimage))
	}
	return marshalCanonicalVectorObjectV1(entry.Fields, values, "")
}

// VerifyEd25519CanonicalVectorV1 proves the frozen wire widths and signature
// against the same message bytes used by positive generation.
func VerifyEd25519CanonicalVectorV1(publicKeyHex, signatureHex string, message []byte) error {
	publicKey, err := hex.DecodeString(publicKeyHex)
	if err != nil || len(publicKey) != ed25519.PublicKeySize {
		return errors.New("Ed25519 public key must be exactly 32 raw bytes")
	}
	signature, err := hex.DecodeString(signatureHex)
	if err != nil || len(signature) != ed25519.SignatureSize {
		return errors.New("Ed25519 signature must be exactly 64 raw bytes")
	}
	if publicKeyHex != strings.ToLower(publicKeyHex) || signatureHex != strings.ToLower(signatureHex) {
		return errors.New("Ed25519 wire must be lower-hex")
	}
	if !ed25519.Verify(ed25519.PublicKey(publicKey), message, signature) {
		return errors.New("Ed25519 signature verification failed")
	}
	return nil
}
